-- BigNoteBox UI/PatchHistory.lua -- every release's patch notes (ALL-511)
--
-- GENERATED by _work/tools/patch-history.lua from UI/WhatsNewData.lua at each
-- release tag. Do not edit by hand: change WhatsNewData.lua and run
--   luajit _work/tools/patch-history.lua
-- from the repo root (Release Routine, after the version bump).
-- Newest first; time = the release commit's time. The Patch notes system
-- folder (Core/SystemNotes.lua, UI/WhatsNew.lua) builds its notes from it.

local BNB = BigNoteBox

BNB.PATCH_HISTORY = {
    { version = "1.30.0", time = 1792346674, entries = {
        "|cff66bb6aNew:|r Settings profiles: Settings > Advanced starts with Profiles. Keep different settings and window layouts for different characters (a bank alt, a raider): clone the one you use or start a blank one with the setup wizard, rename, delete, and export / import a profile as a code to share. Every character starts on Default; the profile you pick is the one it loads with. Notes are shared by every profile, and the full JSON backup keeps every profile too (importing it adds them; one whose name you already have, such as Default, comes in as \"Default (1)\"). Danger Zone can reset just the profile in use, or all settings and profiles.",
        "|cff66bb6aChange:|r Right-click menus: the menu of an item or spell link, and of a Reference Box entry, shows its icon beside the name; a web link's menu leaves out https:// and www. so more of the address shows. The menu of a link to another note has Open as sticky note, Share note, Copy note to clipboard and Copy / Move to...",
        "|cff66bb6aChange:|r Right-click menus: an item, spell or other game link in the note you are editing (also in View and Focus mode) has Add to Reference Box. A web link's menu shows a link symbol in front of the address.",
        "|cff66bb6aChange:|r Reference Box: Insert at text cursor reads Insert at bottom of note until you click into the note's text, and puts the link on a new line at the end instead of being greyed out.",
        "|cff66bb6aChange:|r Focus mode: link menus work there. Share note, Send to Chat, Copy / Move and the copy box open over Focus mode, Add to Reference Box opens the box beside it, and rows that need a game window (item card, dressing room, chat line, map) close Focus mode first. Focus mode's bottom bar has the Reference Box and Add task buttons too.",
        "|cff66bb6aChange:|r Settings > Backup: three buttons, Full backup (notes, templates, tokens, tag colours and settings profiles), Settings backup (profiles only) and Selective backup (pick JSON or Markdown and which notes and parts go in). Each copies straight away with Ctrl+C. Importing a backup that holds more than notes shows what is in it, so you can untick parts.",
        "|cff66bb6aChange:|r Back up first, offered before an import or a migration, shows the copy popup: Ctrl+C copies your notes and the import goes on, Esc stops it.",
        "|cff66bb6aChange:|r Simplified Chinese: settings profiles, the new Backup page and the new right-click menu lines are translated.",
        "|cff66bb6aFixed:|r Reference Box: the right-click menu no longer opens under the entry's tooltip.",
        "|cff66bb6aFixed:|r Tags: a tag that starts with a Chinese (or other non-Latin) letter is no longer broken when it is added, and tags already broken this way are repaired. A backup of notes with such a tag no longer comes up empty.",
    } },
    { version = "1.29.0", time = 1792321238, entries = {
        "|cff66bb6aNew:|r Right-click a link in a note, rich or normal, for a menu: Send to chat, Show and Try on for items; Set waypoint, Show on map, Send to chat and Copy /way for waypoints; Open note and Share to chat for links to other notes; Send to chat and Copy link for web links.",
        "|cff66bb6aNew:|r The right-click menu in the note text now holds the note token groups, the same as the toolbar's token button, in place of the old insert rows; new token {{datetime}} for the date and time together.",
        "|cff66bb6aNew:|r Links to other notes show in that note's title colour, and follow it when it changes.",
        "|cff66bb6aChange:|r Note tokens in a normal note become their value as you type or pick them (your gold, an item's link, your own tokens); rich notes keep them live and filled each time they are shown. A rich note made normal gets the values of that moment.",
        "|cff66bb6aChange:|r Clicking an item or other game link in a normal note works as in a rich note (the card, Ctrl+click to try it on); Shift+click sends a link to chat in both, opening the chat line if it is closed.",
        "|cff66bb6aChange:|r Send to chat goes straight into BigChatBox's chat line when BigChatBox is on.",
        "|cff66bb6aChange:|r Reference Box right-click menus show the entry's name at the top and an icon on every row.",
        "|cff66bb6aChange:|r The note token lists call their groups Here and now and Character, and their tooltips say how tokens fill in rich and normal notes.",
        "|cff66bb6aChange:|r The note toolbar's overflow menu uses short names (Restore point, History, Alarm, Copy / Move, Share, Show on map); the longer text is in the tooltip.",
        "|cff66bb6aChange:|r Settings > Backup shows the Rescue section only while there are notes to rescue, at the top of the page, so the page no longer needs a scrollbar.",
        "|cff66bb6aChange:|r Simplified Chinese: everything added since the last translation is translated (templates, tags, note tokens, links, Rescue and more).",
        "|cff66bb6aFixed:|r Up and Down move through the token list again in notes, Focus mode, sticky editing and the tl;dr boxes.",
        "|cff66bb6aFixed:|r Pressing Enter at the bottom of a note scrolls the note along, so the line you are typing stays in view.",
        "|cff66bb6aFixed:|r Clicking the note title to rename it frames only the title, not the tl;dr line above it.",
    } },
    { version = "1.28.0", time = 1792272267, entries = {
        "|cff66bb6aNew:|r Left-aligned paragraphs in rich notes: {p:l}...{/p}, with its own toolbar button next to the plain paragraph one.",
        "|cff66bb6aNew:|r Note tokens: write {{me}}, {{class}}, {{spec}}, {{ilvl}}, {{guild}} or {{here}} in a note and it shows the reader's own name, class, item level and so on (in rich notes, stickies, toasts, the tl;dr and Send to Chat). Type {{date}}, {{time}}, {{zone}}, {{target}} or {{coords}} and it turns into today's date, the zone you are in, a waypoint link to where you stand and so on as you type (Ctrl+Z brings the token back).",
        "|cff66bb6aNew:|r Note tokens for game data: {{item:6948}} shows the item's icon and link, {{quest:id}} and {{achievement:id}} a tick once done (a red cross until then), {{currency:id}} how much you have, {{rep:id}} your standing, {{mount:id}} and {{pet:id}} whether you have them, {{spell:id}} the spell. A new toolbar button lists every token: hover one to see what it does and what it gives right now, click to put it in the note.",
        "|cff66bb6aNew:|r Note tokens for money, resets and lockouts: {{gold}} shows your money with its coins, {{reset:weekly}} and {{reset:daily}} count down to the reset, {{lockout:name}} shows the bosses you have killed in that dungeon or raid on each difficulty (or \"not saved\"), {{lockouts}} every lockout you have. Tokens now update by themselves while the note is open: level up, change zone, loot money, turn in a quest, kill a boss, and the note follows.",
        "|cff66bb6aNew:|r Note templates: the New Note window has template cards (Blank, Boss strategy, Weekly checklist, Journal) and a More page with ten more (Dungeon route, Daily checklist, Farming route, Collection hunt, Crafting shopping list, Player / applicant, Guide / quest chain, Alt status, IOU, Raid night). The IOU template keeps track of what you owe and what others owe you, gold, items or reagents, ticked off when settled. A template fills in the title, icon, colour, text, tags and task list; checklists untick themselves at the daily or weekly reset, and Boss and Dungeon notes pop up in the instance you made them in.",
        "|cff66bb6aNew:|r Your own note templates: right-click a note > Actions > Save as template, pick what goes with it (tags, tasks, Reference Box, look, situation), and it shows at the top of the New Note window's More page. Settings > Notes > Templates renames, duplicates, replaces or deletes them; duplicate a built-in for a copy you can change. Right-click a template on the More page for the same choices, and Share gives a code anyone can paste in Import shared note to get the template. Your templates are in the JSON backup too.",
        "|cff66bb6aNew:|r Your own note tokens: Settings > Notes > Note tokens makes {{raidtime}} stand for any line of text, which can use other tokens too (\"Wed and Sun 20:00, {{me}} brings {{item:6948}}\"). They fill wherever note tokens do, are listed under My tokens on the token button, and go into the JSON backup.",
        "|cff66bb6aNew:|r Type {{ in a note and a list of tokens opens right under the cursor: keep typing to narrow it, Up / Down to pick, Enter or Tab to put it in. Works in the editor, Focus mode, sticky editing and the tl;dr boxes.",
        "|cff66bb6aNew:|r Tags for one note: right-click a note > Add tags / Edit tags opens a small window to add tags (several at once with commas), remove them, or tick them from a list of every tag you use. Right-click a tag under the note for Filter, Rename on this note, Remove, Colour and Edit tags.",
        "|cff66bb6aNew:|r Tag colours: give a tag one of twelve colours from its right-click menu (on a note, in the tag window or in the Tag Manager). Its chips are tinted on every note, and the tag tree, the Tag Manager and the tag suggestions show it too. Tags named after a class or a faction (Priest, Shaman, Horde, Alliance...) start in the game's colour for it.",
        "|cff66bb6aNew:|r Links in notes (spells, quests, tokens) and Reference Box entries show a pointing cursor while you hover them, items in notes and in the Reference Box an inspect cursor, links to other notes a trainer cursor, web links a map pin cursor, and waypoint links and waypoint rows a directions cursor (Retail and WoW Forever).",
        "|cff66bb6aChange:|r The tl;dr line now sits above the note title, bigger and easier to read, with a button at its end: click it to add or edit the tl;dr right there (Enter saves, Esc cancels, the arrow has your snippets).",
        "|cff66bb6aChange:|r The rich note toolbar has icons in place of the H1 / Pc / Col text buttons, at the same height as the formatting toolbar, and Live Preview is an icon too that shows whether the preview is open.",
        "|cff66bb6aChange:|r The formatting toolbar keeps its note actions (restore, history, alarm, copy / move, share, map) in an overflow menu when the window is too narrow for them, and the icons and dividers have more room.",
        "|cff66bb6aChange:|r On a narrow main window the line under the title drops the coordinates, shortens the dates and then the counts instead of running into itself.",
        "|cff66bb6aFixed:|r Tags that differ only in case are one tag again: \"warcraft\" joins an existing \"WarCraft\" whichever way it was added (templates, imports, player notes), and existing look-alikes are merged into one. New tags keep the rest of their capitals (\"WoW Forever\").",
        "|cff66bb6aFixed:|r \"Created 1 weeks ago\" now reads \"1 week ago\" (month and year too)",
        "|cff66bb6aFixed:|r Undo after a toolbar insert (bullet, timestamp, Reference Box entry, waypoint or note link) takes away only the insert, not the words you typed just before it.",
    } },
    { version = "1.27.0", time = 1792159148, entries = {
        "|cff66bb6aNew:|r Search in Settings: a search box under the tabs finds any setting by its name, heading or tooltip; pick a result and Settings opens that page, scrolls to the setting and flashes it.",
        "|cff66bb6aNew:|r Oracle search: start with \"o\" to search the settings instead of your notes (\"o font\"); Enter opens Settings at that setting.",
    } },
    { version = "1.26.0", time = 1792096316, entries = {
        "|cff66bb6aNew:|r Undo and redo can be kept between sessions: switch it on under Settings > Modules > Undo / Redo and each note's undo steps are still there after a reload or logout, for 1 to 30 days (7 by default). It is stored by the new BigNoteBox History addon that comes with BigNoteBox, the page shows how much space it takes and lists every note that has saved steps (click a title to open the note, X to delete just that note's steps), and one button deletes it all.",
        "|cff66bb6aNew:|r Rescue notes: if notes ever disappear without being deleted (a damaged or replaced notes file), they can be brought back from BigNoteBox History: each with its newest text and everything else as it was at your last logout or reload (look, tags, tasks, Reference Box, situations, alarm, its character), plus a \"Rescued\" tag. An alarm that was due meanwhile does not ring, it is listed in the Alarms window. The Rescue list is on Settings > Modules > Note History, with a button to it on Settings > Backup and in the History window, and BigNoteBox offers it by itself at login if all your notes are gone. A note that is suddenly empty can get its text back the same way.",
        "|cff66bb6aNew:|r Settings > General: a Dukul.net button at the start of the link buttons under More Features copies the link to Dukul.net.",
        "|cff66bb6aNew:|r Data broker bars: BigNoteBox shows your note count and the notes for where you are in Titan Panel, XIV Databar and other data broker bars (pick what it shows, or icon only, under Settings > Advanced). Its tooltip, on the minimap button too, lists the notes here and the 10 last edited notes with their icons and title colours.",
        "|cff66bb6aNew:|r Player notes update themselves: targeting or inspecting a player with a note keeps their level, guild, item level and gear current, and the note counts how often you have met (First met, Last seen, Encountered, Updated). Only the part above the Notes heading changes; what you write under Notes is never touched. Settings > Modules > Player & NPC Notes. Typing above Notes warns you first, and the note's right-click menu can stop or restart the updates.",
        "|cff66bb6aNew:|r Ctrl+click a /way line in a normal note (editor, Focus mode or sticky) to place the waypoint; Ctrl+Shift+click opens the map at it.",
        "|cff66bb6aNew:|r Waypoint links and note links: two new editor toolbar buttons put a link at the cursor, in normal and rich notes. A waypoint link (where you stand, a place you type, or one of a note's waypoints) places the waypoint when clicked; Shift+click puts a map pin in chat, Ctrl+click copies it as a /way line, Alt+click shows it on the map. A note link opens that note (Shift+click as a sticky) and keeps working when the note is renamed; a deleted note's links turn grey, and Shift+click on one restores the note from the Trash. Player and NPC notes write the place you met as a waypoint link. Links are turned into map pins and plain text when a note is sent to chat.",
        "|cff66bb6aChange:|r The Undo / Redo settings moved from the Notes tab to their own page under Settings > Modules.",
        "|cff66bb6aChange:|r Note History (the earlier versions of your notes) is now kept in the BigNoteBox History addon instead of the notes file, so the notes file stays small. Your existing versions move over by themselves during your first two logins or reloads, nothing is lost. BigNoteBox History comes with BigNoteBox and should stay enabled: if it is missing or disabled, a notice says so at login and Note History is off until it is back.",
        "|cff66bb6aFixed:|r A player note open as a sticky or in the editor shows the new text at once after \"Update gear and note\", and unsaved changes to that note are no longer lost when you use it.",
        { forever = true, "|cff66bb6aFixed:|r The Reference Box no longer shows a Transmog gear list that repeats the regular gear on players with a ranged weapon and no transmog; inspect notes now list the ranged item." },
    } },
    { version = "1.25.0", time = 1791888606, entries = {
        "|cff66bb6aNew:|r Top bar menu. Pick which icons stay on the top bar and which go into the menu; icons that do not fit a narrow window move into it instead of covering the sort buttons. The sidebar toggle now lives at the bottom of this menu.",
        "|cff66bb6aNew:|r Two new icon categories, Stone tablets and Storage (49 bags).",
        "|cff66bb6aChange:|r Toast style arrows and button are greyed out while Follow my faction is ticked.",
        "|cff66bb6aFixed:|r In a narrow window the Select mode buttons no longer run off the window: the ones that do not fit are in the top bar menu.",
        "|cff66bb6aFixed:|r Turning off Sticky Notes no longer leaves an empty gap in the note's action bar.",
        "|cff66bb6aFixed:|r The right-click menu in a note now opens anywhere in the writing area, not only over the text.",
        { classic = true, "|cff66bb6aNew:|r Many more note icons: letters, books, race heads, faction tokens and gifts." },
    } },
    { version = "1.24.0", time = 1791830453, entries = {
        "|cff66bb6aNew:|r Item, spell and quest links in rich notes can be clicked as in chat: click shows the item card, Shift+click puts the link in chat, Ctrl+click opens the dressing room.",
        "|cff66bb6aNew:|r Hover an item, spell or quest link in a plain note to see its tooltip.",
        "|cff66bb6aNew:|r Shift+click an item while typing in a note to put its link in the text.",
        "|cff66bb6aNew:|r An item, spell, quest or pet you drop or Shift+click into a note is also added to its Reference Box (Settings > Reference Box, on by default).",
        "|cff66bb6aNew:|r A Reference Box button in the editor toolbar lists the note's Reference Box entries: click one to put it into the text at the cursor. Alt+click an entry in the Reference Box does the same.",
        "|cff66bb6aNew:|r Mounts and your own battle pets dropped into a note are links too.",
        "|cff66bb6aNew:|r Gear in inspect notes is made of item links: hover for the tooltip of the item as worn. Older notes get them with \"Update gear and note\" on the next inspect.",
        "|cff66bb6aNew:|r Skin mode: a new OLED Flat skin, pure black with no borders or divider lines.",
        "|cff66bb6aNew:|r Player notes say where you met the player, and both player and NPC notes get a /way line to the spot (a clickable link in rich notes).",
        "|cff66bb6aChange:|r Skin mode: the Markup and Note tabs under a rich note follow the skin brightness, and their icon and label are centred.",
        "|cff66bb6aChange:|r Skin mode: the selected tab in Settings shows its name in the skin's heading colour, so it reads well on every skin.",
        "|cff66bb6aChange:|r Undo and Redo remember each note's history for the whole session, also after switching notes, using Focus mode or editing the note as a sticky.",
        "|cff66bb6aChange:|r On a narrow main window the editor toolbar hides its right-hand buttons, then the font and size pickers, instead of drawing them over each other.",
        "|cff66bb6aFixed:|r The rich note icon beside a note's title shows its tooltip again, instead of a click on it opening the title for editing.",
        "|cff66bb6aFixed:|r An item dropped on the empty part of a note, below the text, is added at the end instead of being lost.",
        "|cff66bb6aFixed:|r Reference Box > Insert at text cursor now counts as a change to the note and can be undone.",
        "|cff66bb6aFixed:|r The green edit glow on a sticky note sometimes did not show until you scrolled or moved the cursor.",
    } },
    { version = "1.23.1", time = 1791740470, entries = {
        "|cff66bb6aChange:|r The bundled fonts now ship with their license files (Assets/Fonts/OFL.txt and OpenDyslexic-LICENSE.txt).",
        "|cff66bb6aChange:|r Simplified Chinese: every string added since v1.21 is translated, and the older strings use the same words throughout (toasts, alarms, Reference Box, Oracle, snooze).",
        { classic = true, "|cff66bb6aChange:|r The Report a bug button sits beside the main window, with a red glow, as on WoW Forever (it was beside the Settings window)." },
        { classic = true, "|cff66bb6aChange:|r The language selector is now on Classic too (Settings > General and the setup wizard)." },
        { classic = true, "|cff66bb6aFixed:|r Reference Box \"Show IDs\" adds the ItemID and SpellID lines to tooltips (they were missing)." },
        { classic = true, "|cff66bb6aFixed:|r TBC Anniversary and MoP: the tl;dr line shows in the game tooltip of a player or NPC with a note." },
    } },
    { version = "1.23.0", time = 1791716679, entries = {
        "|cff66bb6aNew:|r The top bar's Send button opens a note search: type a name, pick the note with the mouse or the arrow keys, and it goes straight to the Send to Chat window, no need to open it first.",
        "|cff66bb6aNew:|r Oracle prefix \"m\" sends the note you pick to the Send to Chat window.",
        "|cff66bb6aNew:|r After an update, the patch notes no longer open a window over the screen: they come as a pinned, favourite note (tagged Bnb and the version number) and a toast that waits for your click. The next update replaces that note, unless you edited it or removed its Bnb tag. The What's New window is still on the version button in Settings > General.",
        "|cff66bb6aNew:|r Settings > Modules > Toasts: \"Messages from BigNoteBox\" turns the update and welcome toasts off (the notes are still made).",
        "|cff66bb6aNew:|r A fresh install starts with a welcome note from Dukul, pinned at the top, with a toast pointing to it.",
        "|cff66bb6aNew:|r Settings > General: buttons under More Features copy the link to BigNoteBox on GitHub, CurseForge, Wago and WoWInterface.",
        "|cff66bb6aNew:|r tl;dr notes: give a note one short line (up to 80 characters) at the top of Note Settings > Situation, typed or picked from a list of snippets (KOS, Friendly, Avoid, Vendor / trader and more). It shows under the note title, in the game tooltip of the player or NPC the note is about, on the note icon at the Target and Focus frames, and on the note's situation toast. Settings > Modules > tl;dr turns it on or off, chooses where it shows and edits the snippet list.",
        "|cff66bb6aNew:|r Hovering a note in the note list shows a small box with its tl;dr, next alarm, situations and waypoints; hovering the note icon on the Target or Focus frame shows the same box. Settings > Modules > tl;dr, \"Note details when hovering the note list\" turns the list box off.",
        "|cff66bb6aNew:|r Toast styles in a picker: on Settings > Modules > Toasts and in a note's Toast window, click the style name to see every style as a real toast, two side by side (the name shows on hover). Click one to use it, double-click to use it and close, Revert to go back; the arrows beside the name step through them. \"Follow my faction\" / \"As in Settings\" sits in the picker too. A note's picker shows that note's own toast.",
        "|cff66bb6aNew:|r Situations can be on or off: on the Situation tab a green situation is on, a grey one is kept on the note but never shows. Click one to switch it, double-click to edit it.",
        "|cff66bb6aNew:|r Every new player or NPC note gets a situation for that player or NPC, off unless you choose otherwise: Settings > Modules > Situations has \"Turn on the player situation\" and \"Turn on the NPC situation\", each with \"Show the note as a toast\" under it. So a KOS note is: make the note, pick KOS as its tl;dr, done.",
        "|cff66bb6aNew:|r Note Settings > Situation, Show as: \"Show nothing\". The situation still marks the note and places its waypoints, but no toast or sticky pops up.",
        "|cff66bb6aChange:|r Toasts that pop up together (at login, entering a zone) now come in one after another and leave one at a time, oldest first, instead of all at once.",
        "|cff66bb6aChange:|r Toasts waiting for room show as a small \"+N\" box after the last toast, counting down as they come in. A toast's list (tasks, grouped situations) is a box of its own, dark like a sticky note, or in your skin's colours in skin mode.",
        "|cff66bb6aChange:|r BigNoteBox's code is now licensed under the GNU GPL v3 (it was MIT). The logo and icon are All Rights Reserved; the rest of the art is Blizzard's. See LICENSE and LICENSE-ASSETS.",
        "|cff66bb6aChange:|r Suggestion lists take the arrow keys: Up / Down pick a row, Enter or Tab takes it, Esc closes the list (Situations add row, waypoint sub-zone, note list \"#\" tags, Send directly names).",
        "|cff66bb6aChange:|r Note Settings > Situations > Waypoints: clicking \"(Addon required)\" or the ? now opens Settings > Advanced > Addon integrations instead of a separate popup.",
        "|cff66bb6aChange:|r The collapsed note list shows a note's title when you hover it.",
        "|cff66bb6aChange:|r Toasts show in the upper left instead of the middle of the screen. A toast position you placed yourself stays where it is.",
        "|cff66bb6aChange:|r Settings > Advanced > Addon integrations lists DialogueUI and Immersion too, with what BigNoteBox does with each (Immersion is not listed on TBC Anniversary, which it has no version for).",
        "|cff66bb6aFixed:|r Alarm window: the day boxes under Repeat name the full day when you hover them (\"Ring on Monday\").",
        "|cff66bb6aFixed:|r Toasts growing Left or Right: a toast with a list (tasks, grouped situations) no longer sits higher than the others; its list is now a box of its own beside it.",
        "|cff66bb6aFixed:|r Rich notes in the main window no longer cut off the end of each line when opened (it only went away after resizing the window).",
        "|cff66bb6aFixed:|r A toast for a player note now shows the player's face while you have them targeted, as the note list does (it showed the plain note icon). Its right-click menu and alarm toasts too.",
        { forever = true, "|cff66bb6aChange:|r The language selector is back in the setup wizard and Settings > General: a forced language now stays through reloads." },
        { classic = true, "|cff66bb6aChange:|r Reference Box side tabs sit under the window edge." },
        { classic = true, "|cff66bb6aChange:|r Addon integrations no longer lists WaypointUI and MapPinEnhanced, which have no Classic version." },
        { classic = true, "|cff66bb6aChange:|r The icon picker has no \"All game icons\" list on Classic: almost none of those icons exist there, so Classic uses the curated icons." },
        { classic = true, "|cff66bb6aFixed:|r Three icon frames that do not exist on Classic (Golden Hunter, Solar Flare, Corner Ornament) are no longer offered there." },
        { classic = true, "|cff66bb6aFixed:|r Note Settings > Situations > Waypoints: without a waypoint addon, the red install hint no longer runs out of the window (the line is gone; \"(Addon required)\" says it)." },
    } },
    { version = "1.22.0", time = 1791630557, entries = {
        "|cff66bb6aNew:|r Alarms: set the defaults for new alarms (snooze time, glow type, glow mode, glow colour) in Settings > Modules > Alarms. Alarms set to \"Default\" follow them.",
        "|cff66bb6aNew:|r Alarm popup: alarms waiting their turn show as bars under the popup. Click one to show it now.",
        "|cff66bb6aNew:|r Before an import or a migration, BigNoteBox offers to save a backup of the notes you already have.",
        "|cff66bb6aNew:|r Rich notes: /way lines (as TomTom and Wowhead write them, \"/way Zone 45.2 60.1\" or \"/way #84 45.2 60.1\") are clickable links. Click to place the waypoint (TomTom, or the game's map pin), Shift+click to see it on the world map.",
        "|cff66bb6aNew:|r Situations > Waypoints: \"Show on map\" in a waypoint's right-click menu, or Shift+click the row, opens the world map with a marker on the spot.",
        "|cff66bb6aNew:|r Situations: the player name box suggests your friends (Battle.net friends too), your guild and your group, in class colours.",
        "|cff66bb6aNew:|r Rich notes: broken formatting tags (a {p} never closed, a {/p} closing a heading, a close tag with nothing open) show as \"Markup: N to fix\" next to the word count, with the details on hover. They are fixed in the text when you open another note or close the window; Note History keeps the text from before.",
        "|cff66bb6aNew:|r Settings > Advanced > Addon integrations: a page of its own with one section per addon (BigChatBox, TomTom, WaypointUI), with its logo, what it does and whether it is active, and the tab shows how many you have. An addon you do not have has a button that copies its CurseForge link.",
        "|cff66bb6aNew:|r Reference Box: add mounts and battle pets straight from the Collections journals (drag them in or Shift+click), with their model.",
        "|cff66bb6aChange:|r Set alarm: \"Every N days\" has < > buttons to change the number.",
        "|cff66bb6aChange:|r Situations: Add with nothing typed adds where you are now (zone, sub-zone, instance) or your target (player, NPC, guild).",
        "|cff66bb6aChange:|r Danger Zone: the confirm button says how much it changes, like \"Delete all 312 notes\".",
        "|cff66bb6aChange:|r Copy boxes from link buttons show the start of the link you are copying.",
        "|cff66bb6aChange:|r Skin mode: text buttons look pressed while held (the label moves down a pixel).",
        "|cff66bb6aChange:|r Sticky notes: the border has its own opacity slider (Appearance), so the background opacity no longer fades the border.",
        "|cff66bb6aChange:|r Sticky notes: the scrollbar shows only while the pointer is over the note.",
        "|cff66bb6aChange:|r Sticky notes: the window border is picked from a thumbnail grid with < > arrows, as the background is. Note Settings' icon frame row has the < > arrows too.",
        "|cff66bb6aChange:|r Skin mode: slider tracks are see-through (70%) instead of solid black.",
        "|cff66bb6aChange:|r Skin mode: the OLED preset's softer white also reaches sticky note text that still has its default colour.",
        "|cff66bb6aChange:|r Changing the note font updates skin-mode button labels and the welcome screen at once, without a reload.",
        "|cff66bb6aChange:|r NPC notes show the creature's portrait again (switched off in v1.21.1 while a crash was tracked down).",
        "|cff66bb6aChange:|r The toast position anchor is now exactly the size of a toast: a see-through box in normal mode, the skin's colours in skin mode.",
        "|cff66bb6aChange:|r Esc closes the window in front first: Settings or Trash opened over Note History now close before it.",
        "|cff66bb6aChange:|r The note list collapses on its own when the main window is made narrower than 530, and comes back when you widen it again.",
        "|cff66bb6aChange:|r Settings > General: BCB Integration moved to Advanced > Addon integrations; a smaller More Features button sits beside Language.",
        "|cff66bb6aChange:|r Settings tooltips: what a checkbox does when on and when off is shown as two paragraphs, with On: and Off: in green (or the skin colour).",
        "|cff66bb6aFixed:|r Import: pressing Esc on the \"notes for another character\" question now cancels the import instead of importing.",
        "|cff66bb6aFixed:|r Skin mode: the font cards in Note Settings and sticky note settings use the skin's colours instead of the old green.",
        "|cff66bb6aFixed:|r Target notes: a note imported from a file is found again when you make a note of the same NPC (it asks first instead of making a silent \"(Duplicate)\"), and a repeated press for the same target makes one note.",
        "|cff66bb6aFixed:|r Mount stands (one NPC ID shared by several invisible mounts, like the Orgrimmar Trading Post): each stand gets its own note, and the Reference Box shows its mount instead of an empty viewer.",
        { retail = true, "|cff66bb6aNew:|r MapPinEnhanced support (version 4.0 and newer): situation waypoints go to MapPinEnhanced as named pins in a BigNoteBox group, several at once, \"Don't track it\" is respected, and they are removed again when you leave. Navigate, Show on map and the coordinate button use it too. Settings > Advanced > Addon integrations has a MapPinEnhanced section, which says \"Needs update\" for older versions." },
        { forever = true, "|cff66bb6aChange:|r Skin mode: the beta notice is drawn in the skin's look." },
        { forever = true, "|cff66bb6aChange:|r Skin mode uses the plain action bar icons, as on Retail (the detailed Forever icons stay in normal mode)." },
        { classic = true, "|cff66bb6aChange:|r Skin mode: the beta notice is drawn in the skin's look." },
    } },
    { version = "1.21.1", time = 1791568811, entries = {
        "|cff66bb6aFixed:|r The game no longer crashes to desktop when you make or open a note of an NPC while the Reference Box is open.",
        "|cff66bb6aChange:|r NPC notes show their note icon instead of the creature's portrait (the portrait was part of that crash).",
    } },
    { version = "1.21.0", time = 1791489579, entries = {
        "|cff66bb6aNew:|r Situation toasts are rebuilt: one toast per note, stacked in the direction you pick (down, up, left or right), each with its own timer, up to 1-10 at once (more wait their turn), sliding into place. Pointing at a toast pauses them all. Settings > Modules > Toasts has a Test button, a new toast position anchor with Reset, and a choice for toasts in combat (show, wait until combat ends, or skip). The old grouped toast is still there as a layout.",
        "|cff66bb6aNew:|r Toast styles: the toasts now look like the game's loot toasts, Horde or Alliance by your faction. Untick Follow my faction to pick another style: Plain black, Skin colour (in skin mode), or the other faction's loot toast. Toast size makes them bigger or smaller.",
        "|cff66bb6aNew:|r Toasts show more: the note's icon with its icon frame (an NPC note shows the creature), why it showed (\"Thrall is here\", \"Vendor open\", the place), the first line of the note and a map pin when the note has a waypoint. Each can be switched off in Settings > Modules > Toasts.",
        "|cff66bb6aNew:|r Right-click a toast: Open, Open as sticky note, Navigate, Not again today, a toast style and time on screen for just that note, and Dismiss.",
        "|cff66bb6aNew:|r Toasts can play a sound (the alarm sounds, off by default).",
        "|cff66bb6aNew:|r Toasts are a module of their own (Settings > Modules > Toasts), with every toast setting on its page and a switch for each kind: situation notes and tasks. Switched off, no toast shows; situations still match, place waypoints and open stickies.",
        "|cff66bb6aNew:|r Note Settings and sticky settings > Situation: a Toast... button sets this note's own toast style and how long it shows, with a Test button.",
        "|cff66bb6aNew:|r Alarms can show as toasts (Settings > Modules > Alarms > Show alarms as). An alarm toast stays until you click it: left click dismisses, right click opens the note, snoozes or dismisses. Alarms you missed while offline or in combat now come as toasts instead of popups.",
        "|cff66bb6aNew:|r When the player or NPC you target or focus has a note, the note's icon shows at the corner of the Target and Focus frame portraits. Click it to open the note (Settings > Modules > Player & NPC Notes).",
        "|cff66bb6aNew:|r 11 new alarm and toast sounds: Apple Pay, Heartbeat, Horror Warning, Ka-Ching, MGS Alert, Quack, Sad Trombone, Toasty, Violin Sting, Warning Alert and Whistle.",
        "|cff66bb6aNew:|r Toasts show on top of all windows, Settings and dialogs included (Settings > Modules > Toasts > Show on top of all windows, on by default).",
        "|cff66bb6aNew:|r Point at a toast to show a close button in its top right corner; an alarm toast closed this way dismisses the alarm.",
        "|cff66bb6aChange:|r New toolbar icons in the main window: in normal mode with their own hover, pressed and greyed-out pictures, in skin mode drawn in a colour that pairs with the skin preset. On Retail and Classic the note editor's action bar uses the more detailed icons from WoW Forever in normal mode.",
        "|cff66bb6aChange:|r Context Popup is now the Situations module: switched off, no situation checks, popups or automatic waypoints, the Situation tab says it is off, and the situation markers hide. Notes keep their situations, and Navigate still works.",
        "|cff66bb6aChange:|r Trash, Note History and Alarms rows use new hover and selection art in normal mode, and Alarms rows highlight on hover.",
        "|cff66bb6aChange:|r New alarm, favourite and situation markers on note icons in the note list and on sticky notes (normal mode); the character's class icon is round to match. A new marker shows on notes that place a waypoint when their situation matches.",
        "|cff66bb6aChange:|r More checkboxes explain themselves on hover: the alarm weekdays and snooze, Send to Chat, export formats, Copy/Move, the migrate window, the setup wizard, and the Character Sidebar and Trash switches.",
        "|cff66bb6aChange:|r The note button in quest, gossip and book windows is now called Note Capture (Settings > Modules > Note Capture), so it is no longer confused with the Quick Note button and F7.",
        "|cff66bb6aChange:|r The Settings window is a little wider in normal mode, so every tab name fits (it was already this wide in skin mode, where the pages now use the full width).",
        "|cff66bb6aChange:|r The Reference Box window is now three parts that each follow their own module: attachments follow Reference Box, the player / NPC model follows Player & NPC Notes, and tasks follow Tasks. With the Reference Box off, player and NPC notes still show their model.",
        "|cff66bb6aChange:|r The Get BigChatBox window has the look of the Report a bug window, with a button that copies the CurseForge link.",
        "|cff66bb6aChange:|r Skin mode: scrollbars and sliders take the skin colours, and dropdowns are drawn like the other skin buttons, with a small arrow button at the end and their open list in the skin colours.",
        "|cff66bb6aChange:|r Settings > Advanced: debug mode is a checkbox of its own (for this session only, also /bnb debug on and off), and the developer tools are a page in Settings. They need the separate BigNoteBox_Dev addon, now a download on each GitHub release.",
        "|cff66bb6aChange:|r Less gold everywhere: headings take one colour (in skin mode a colour that pairs with your skin preset, a soft warm gold on Obsidian, OLED and Argent; in normal mode a soft green), while checkbox labels, setting names and other text are white. On the OLED skin preset white text is a softer grey. Game tooltips, chat lines and toasts keep their own colours.",
        "|cff66bb6aChange:|r Settings > General: \"by Dukul\" is a button that copies the link to dukul.net.",
        "|cff66bb6aChange:|r New icons on the formatting toolbar under the note title, with a new hover glow; in skin mode they are plain icons in the skin's accent colour, and the font and size boxes look like the other skin dropdowns.",
        "|cff66bb6aChange:|r New icons for the note list's tag tree, favourites, tasks and reset buttons and the list collapse arrow: gold in normal mode, the skin's accent colour in skin mode, with a hover glow.",
        "|cff66bb6aChange:|r The note editor's action bar icons show a soft glow behind them on hover instead of growing (gold in normal mode, the skin's accent colour in skin mode).",
        "|cff66bb6aChange:|r The main window's top bar icons have a little more room between them in normal mode.",
        "|cff66bb6aChange:|r Skin mode: checkboxes are drawn in the skin's colours, in Settings and in the task lists of sticky notes and the Reference Box; sticky note task checkboxes are bigger in both modes.",
        "|cff66bb6aChange:|r Skin mode: the rich note Source / Note tabs show the active tab's icon in the skin's accent colour and dim the other tab.",
        "|cff66bb6aChange:|r Skin mode: the selected font card in Settings, the New note dialog and the setup wizard (and the wizard's other choices) is drawn in the skin's colours instead of green.",
        "|cff66bb6aChange:|r Settings > Appearance: the skin options (preset, brightness, opacity, randomize) only show while skin mode is on, so the font settings move up in normal mode.",
        "|cff66bb6aChange:|r The grouped toast layout looks like the other toasts now and is used only when several notes show at once.",
        "|cff66bb6aChange:|r Skin mode: a new rich-note icon beside the note title, in the skin's accent colour, and the inactive rich tab dims its icon along with its label.",
        "|cff66bb6aFixed:|r The move cursor no longer stays stuck after moving from the main window's top bar into the window.",
        "|cff66bb6aFixed:|r The Trash window showed titles in the heading colour when the note had no title colour; they are white now. Note History shows each note's title in its own title colour.",
        "|cff66bb6aFixed:|r \"Use WoW's default font\" no longer sits right on the font cards in Note Settings and sticky settings.",
        "|cff66bb6aFixed:|r In skin mode, divider lines no longer turn glaring at high skin brightness.",
        "|cff66bb6aFixed:|r In skin mode, the icons on the main window's title bar and other icon buttons no longer turn white at high skin brightness.",
        "|cff66bb6aFixed:|r In skin mode, greyed-out buttons now look greyed out and no longer show a press when clicked.",
        "|cff66bb6aFixed:|r Switching off Dim screen behind ESC sticky notes now takes effect at once, not at the next ESC.",
    } },
    { version = "1.20.1", time = 1791378403, entries = {
        "|cff66bb6aFixed:|r The Oracle help (?) no longer errors while Sticky Notes is switched off",
        "|cff66bb6aFixed:|r With Quick Note switched off, the note button no longer shows in quest, gossip and book windows",
    } },
    { version = "1.20.0", time = 1791375039, entries = {
        "|cff66bb6aNew:|r BigNoteBox now runs on WoW Classic: Classic Era, TBC Anniversary and Mists of Pandaria Classic, as a beta",
        "|cff66bb6aNew:|r The setup wizard asks how you want to use BigNoteBox: Minimal (just write notes), Full, or Custom to pick each module yourself, with a tooltip on every module",
        "|cff66bb6aNew:|r Settings > Modules has Minimal, Full and Custom at the top: one click switches every module to that set",
        "|cff66bb6aNew:|r Alarms can be switched off in Settings > Modules > Alarms. Off hides every alarm button and menu entry and nothing rings; your alarms are kept. Switched back on, repeating alarms carry on from their next time and any other alarm that came due is listed in the Alarms window instead of ringing",
        "|cff66bb6aNew:|r Note History and Focus Mode can be switched off too, in Settings > Modules. Off hides their buttons and menu entries; Note History also stops saving new versions on logout and keeps the ones you have",
        "|cff66bb6aNew:|r Sticky Notes can be switched off in Settings > Modules. Off closes every sticky and hides every way to open one; notes set to open as a sticky (situations, alarms) show as a popup, and the quick note key opens the main window. Switched back on, the stickies that were open come back",
        "|cff66bb6aNew:|r Rich Notes can be switched off in Settings > Modules. Off shows every rich note as plain text with its markup visible, so you can still read and edit it, and hides every way to make a rich note. Your notes stay rich: switch it back on and they look as before",
        "|cff66bb6aNew:|r Player & NPC Notes can be switched off in Settings > Modules. Off hides the Inspect window button, automatic inspect notes, the unit menu entries and the target note key, plus the live target portrait and the Reference Box Model tab. Your player and NPC notes stay in the list as ordinary notes",
        "|cff66bb6aNew:|r Alarms have two new types, Daily reset and Weekly reset: they ring at the reset itself, every day or every week, with no date, time or Repeat to set. \"WoW weekly reset\" moved out of Repeat into these; existing weekly reset alarms carry on as Weekly reset",
        "|cff66bb6aNew:|r Situation waypoints have a Sub-zone column: Pin Here fills it from where you stand, and a double-click on it lets you type one with suggestions. Each waypoint now takes two lines (name and X, Y, then zone and sub-zone) and the list shows four",
        "|cff66bb6aNew:|r 43 new sticky backgrounds from the game, among them four holiday ones under a new Events tab, the four flight maps, quest parchments for Alliance and Horde, and marble, brick and wood",
        "|cff66bb6aNew:|r Sticky notes have a Normal/Rich button that shows a rich note as plain text or as rich text",
        "|cff66bb6aNew:|r Settings > Modules > Sticky Notes can hide the Minimize button and the new Normal/Rich button",
        "|cff66bb6aNew:|r Right-click a note > Open > Open Reference Box (also a choice for the Open click)",
        "|cff66bb6aNew:|r Right-click the icon in the New note window to give the note an icon frame",
        "|cff66bb6aNew:|r Turning a rich note into a normal note can make a restore point first",
        "|cff66bb6aNew:|r Note History's compare shows which tags a restore adds and removes",
        "|cff66bb6aNew:|r Right-click the Transmog gear or Regular gear title in the Reference Box to copy all Wowhead links",
        "|cff66bb6aNew:|r Settings > Backup > Import takes a share code too and opens it in the share preview",
        "|cff66bb6aNew:|r Your own images for rich notes can live in a small addon of your own, so updates no longer wipe them (UserImages/README.txt shows how)",
        "|cff66bb6aChange:|r The New note title is typed in the title colour you picked",
        "|cff66bb6aChange:|r Set Alarm: the Remove Alarm button reads Cancel until the alarm is saved, and Every N days is a plain number field",
        "|cff66bb6aChange:|r The Alarms toolbar button is greyed while no note has an alarm",
        "|cff66bb6aChange:|r Focus mode no longer has a Restore button (the X and Esc already take you back)",
        "|cff66bb6aChange:|r The OLED skin lets you change Window opacity",
        "|cff66bb6aChange:|r New installs hide everything and minimize sticky notes when you enter combat",
        "|cff66bb6aChange:|r Background and icon frame pickers show a name only when you hover a tile",
        "|cff66bb6aChange:|r The waypoint status in Note Settings > Situation lists which waypoint addons are installed",
        "|cff66bb6aChange:|r Bigger section titles in the Reference Box",
        "|cff66bb6aChange:|r The Stone background now uses the game's own rock texture, which makes the download smaller",
        "|cff66bb6aChange:|r The AddOns list shows BigNoteBox's folders together as one group",
        "|cff66bb6aChange:|r The 12 old bundled sticky backgrounds are gone (there are plenty from the game now), so the download is smaller. Stickies that used one go back to a plain background in their own colour; you can delete the BigNoteBox_BGs folder from your AddOns",
        "|cff66bb6aChange:|r Three backgrounds have new names: Dragon Parchment, Sand Stone and Dirty Paper",
        "|cff66bb6aChange:|r New look for the character tabs above the main window, in normal and skin mode",
        "|cff66bb6aFixed:|r In-game alarms rang only once, although they say they ring every day at that time",
        "|cff66bb6aFixed:|r Border brightness above 100% did nothing; it now brightens all the way to 200%, and stickies, Note Settings and the Oracle all use the same 0-200% scale",
        "|cff66bb6aFixed:|r Character tab note counts update at once when notes are created, deleted, restored or moved",
        "|cff66bb6aFixed:|r Send to Chat sent a rich note's formatting tags; it sends plain text now",
        "|cff66bb6aFixed:|r The dropdown in Remove character opened under the window",
        "|cff66bb6aFixed:|r The Copy/Move list could show a character name with no checkbox",
        "|cff66bb6aFixed:|r Sticky notes show the live portrait while the note's player or NPC is your target",
        "|cff66bb6aFixed:|r The Reference Box listed the same gear twice for players with no transmog",
        "|cff66bb6aFixed:|r Some NPC notes showed an empty model viewer",
        "|cff66bb6aFixed:|r Shift-clicking links into the Reference Box works with the newer chat code",
        "|cff66bb6aFixed:|r The setup wizard now closes the Reference Box along with the other windows",
        "|cff66bb6aFixed:|r Importing a broken share code on the welcome screen now says what is wrong with it",
        "|cff66bb6aFixed:|r Send to BigChatBox did nothing when BigChatBox's multi-line box is switched off; the toolbar button now opens Send to Chat instead",
        { retail = true, "|cff66bb6aFixed:|r A Blizzard achievement error when making an inspect note after opening the achievement window" },
        { forever = true, "|cff66bb6aFixed:|r The game could crash to desktop when switching from a rich note to another note" },
    } },
    { version = "1.19.0", time = 1791288381, entries = {
        "|cff66bb6aNew:|r Settings > Modules > Character Sidebar: \"Tabs fill the window width\" makes the character tabs on top of the main window share its whole width (on by default)",
        "|cff66bb6aNew:|r Lock a sticky note in place: Lock in Sticky settings > General or in the sticky's right-click menu keeps its position and size, and everything else still works",
        "|cff66bb6aNew:|r Insert image has \"Keep ratio\": the height follows the width",
        "|cff66bb6aNew:|r Settings > Notes: \"Reset all\" beside \"Lock notes by default\" makes every note follow that setting again",
        "|cff66bb6aNew:|r Remove a character you no longer have: Settings > Modules > Character sidebar now lists every character (note count, \"not seen for N days\" after 90 days) with Hide / Show and Remove, also in the character's right-click menu. Its notes move to another character or Global first",
        "|cff66bb6aNew:|r Settings > Notes: \"New notes belong to\" picks where new notes go: the selected tab (as before), Global, or the character you are playing",
        "|cff66bb6aNew:|r The New note window has a character dropdown beside the title, so a note can go straight to any of your characters",
        "|cff66bb6aNew:|r Settings > Modules > Sticky Notes: turn off the Create task, Set alarm, Open in BigNoteBox and Sticky settings buttons that show when you hover a sticky. The right-click menu still has them all",
        "|cff66bb6aNew:|r Choose which side of the main window Note History, Trash, Alarms, the Tag Manager and the rich preview open on (Settings > Modules on each one's page; the Tag Manager under Settings > Notes)",
        "|cff66bb6aNew:|r Settings > Modules > Window placement: reset the main window's placement and/or size every time you log in or reload",
        "|cff66bb6aNew:|r A situation's waypoint can be placed without taking over your map arrow: tick \"Don't track it\" under the waypoint on the Situation tab",
        "|cff66bb6aNew:|r Share > Send Directly shows how many messages a note takes before you send it; a note too large to send greys out Send",
        "|cff66bb6aNew:|r Receiving a large note by Direct Send now says so in chat while it arrives",
        "|cff66bb6aNew:|r A note can hold several waypoints: the Situation tab lists them under the spot where the note was made (Name, Zone, X, Y). Green ones are placed when the situation matches, grey ones are kept for Navigate; click a row to switch, double-click its name to rename it, its zone to move it to another zone or its X, Y to change the coordinates (not on the spot where the note was made), hover for Navigate and Remove, or right-click for all of these. The list shows with or without a situation",
        "|cff66bb6aNew:|r Right-click a situation on the Situation tab to edit or remove it",
        "|cff66bb6aNew:|r Settings > Modules > Window placement: every window placement setting in one page (main window resets on login, which side Note History, Trash, Alarms, the Tag Manager, the rich preview and the Reference Box open on, the situation popup position and the search bar position). Each one is still on its own page as well",
        "|cff66bb6aNew:|r Focus mode has the formatting toolbar's writing tools (undo, redo, font, size, bullet, timestamp); turn it off in Settings > Notes > Formatting Toolbar",
        "|cff66bb6aNew:|r Right-click in the Focus mode editor for the note's menu, with Close Focus Mode at the bottom",
        "|cff66bb6aNew:|r Shift+Left-click the minimap button to hide or show your sticky notes, Shift+Right-click to open Settings (the addon compartment too)",
        "|cff66bb6aNew:|r Ctrl+Enter in a task adds a sub-task, as Shift+Enter adds a new task",
        "|cff66bb6aNew:|r Search field in the Reference Box Move / Copy window",
        "|cff66bb6aNew:|r Send to Chat is in the note's right-click menu (Actions), no BigChatBox needed",
        "|cff66bb6aNew:|r Dismiss an alarm that has gone off from the Alarm overview (button and right-click). Repeating alarms move on to their next time",
        "|cff66bb6aNew:|r The Welcome panel's Import takes shared note codes as well as JSON backups",
        "|cff66bb6aNew:|r /bnb whatsnew and /bnb features",
        "|cff66bb6aNew:|r Quick notes get the tag Quick Note, and player notes get the player's guild as a tag",
        "|cff66bb6aNew:|r Trash, Note History, the Tag Manager and Alarms look alike: rows as in Note History, buttons at the bottom, and a Select mode with Select all in each",
        "|cff66bb6aNew:|r Trash rows show how long a note has been in the trash and its size; click one to view it, with Restore and Delete on its page. A trashed rich note opens as it looks, with a Markup / Note button to see its source",
        "|cff66bb6aNew:|r Note History has a Select mode: clear the history of several notes at once",
        "|cff66bb6aNew:|r Restore button on each snapshot in Note History, between Compare and Delete",
        "|cff66bb6aNew:|r Tag Manager: select tags and add them to the notes you pick (with a search)",
        "|cff66bb6aNew:|r Alarms: Clear all Alarms, and every alarm shows when it fires (date and time), what kind it is and how it repeats",
        "|cff66bb6aNew:|r Settings > Modules > Character sidebar: sort the character icons Newest first, By name, By class or By notes (most notes first). Pinned characters stay in front",
        "|cff66bb6aNew:|r Notes about Alliance or Horde players show a faint faction crest at the right of their row in the note list",
        "|cff66bb6aChange:|r The note list headers read \"Pinned (N)\" and \"Notes (N)\" in gold with a line running to the right, and the line between pinned and other notes is gone",
        "|cff66bb6aChange:|r Editing a waypoint on the Situation tab opens Name, X and Y boxes together: Tab moves between them, Enter or a click outside saves, Esc cancels. X and Y take a decimal comma too",
        "|cff66bb6aChange:|r Colour grids mark the colour in use; a colour of your own marks the colour picker tile",
        "|cff66bb6aChange:|r Settings > Modules is in alphabetical order. The Icons row is gone: switch all game icons on or off with the \"All game icons\" box in the icon picker",
        "|cff66bb6aChange:|r Sticky settings > General opens with four buttons, Minimal Sticky, ESC Pin, Rich / Normal Note and Lock, each showing what a click will do. Focus mode for stickies is now called Minimal sticky",
        "|cff66bb6aChange:|r Insert icon and Insert image: the size boxes have a list of common sizes (12 to 128) and still take any size you type, up to 256 for icons and 1024 for images",
        "|cff66bb6aChange:|r Stickies, Rich preview and the labs use the main window's resize grip",
        "|cff66bb6aChange:|r Note History and Trash no longer open a second window: a note's history and a trashed note's View open inside the same window, with a back arrow (ESC goes back too). Trash View has Delete beside Restore",
        "|cff66bb6aChange:|r Note Settings > General opens with four buttons, Pin, Favorite, Lock and Rich Note, each showing what a click will do",
        "|cff66bb6aChange:|r Note Settings no longer has a separate Lock section; use the Lock / Unlock button at the top",
        "|cff66bb6aChange:|r New colour palette: 23 named colours in every colour grid",
        "|cff66bb6aChange:|r The note editor's title shows the note's title colour",
        "|cff66bb6aChange:|r In Focus mode the Save button follows the save mode, and automatic mode saves as you type there too",
        "|cff66bb6aChange:|r The \"Hide sticky notes\" button is greyed while there is nothing to hide",
        "|cff66bb6aChange:|r In \"Edited\" sort the list follows the note you type in",
        "|cff66bb6aChange:|r Skin mode: the editor's divider lines take the skin colour",
        "|cff66bb6aChange:|r The character sidebar's Change icon now opens the same icon picker as Note Settings, with search and every icon category",
        "|cff66bb6aChange:|r The Report a bug window follows skin mode",
        "|cff66bb6aChange:|r Copy / Move no longer offers characters hidden from the sidebar, and adds the realm when two characters share a name",
        "|cff66bb6aChange:|r Note Settings no longer has a Note visibility section; use Copy/Move to character in the note's right-click menu, and the editor toolbar's Copy/Move button, now there with the sidebar off too",
        "|cff66bb6aChange:|r The New note window is a little wider, so the font previews have more room",
        "|cff66bb6aChange:|r Note History, Trash, Alarms and the Tag Manager open on the right of the main window, all the same width and as tall as the main window",
        "|cff66bb6aChange:|r Setup wizard: the language choice sits right above Get started",
        "|cff66bb6aChange:|r Setup wizard: pick your skin theme right on the style page; the reload happens when you click Next",
        "|cff66bb6aChange:|r A rich note's Note view shows only the title and the note: the formatting toolbar and the created / edited line come back in Markup view",
        "|cff66bb6aChange:|r Sticky right-click menu: Minimize sticky, Restore sticky, Close sticky, Sticky Note Settings (it opens the sticky's settings) and Open in BNB to Edit",
        "|cff66bb6aChange:|r Settings > Modules has four new pages: Rich Notes (with Live Preview), Note History, Trash and Alarms. Their settings moved there from the Notes and General tabs; Trash can be switched on and off from its row",
        "|cff66bb6aChange:|r Completed tasks sit under a small \"Done (N)\" title and a divider in the Reference Box",
        "|cff66bb6aChange:|r Drag an open sticky note by its icon, as you already could a minimized one",
        "|cff66bb6aChange:|r The Tag Manager button is greyed until a note has a tag, like Trash",
        "|cff66bb6aChange:|r Trash rows are more see-through and show each note's title colour",
        "|cff66bb6aChange:|r JSON is the default format in Settings > Backup > Export Notes",
        "|cff66bb6aChange:|r The setup wizard's last page has Wago.io, CurseForge and WoWInterface buttons, and Dukul.net Homepage",
        "|cff66bb6aChange:|r The resize grip lights up BNB green on hover",
        "|cff66bb6aChange:|r The New note window's \"Sample size\" is now \"Font preview\"; the Icon Frame picker's \"Edge borders\" tab is now \"Shared borders\"",
        "|cff66bb6aChange:|r Wowhead links follow your client (Forever, Classic and so on), in the Reference Box and HTML exports",
        "|cff66bb6aChange:|r The collapsed note list is a little wider and shows square selection, hover and multi-select art around the icons",
        "|cff66bb6aChange:|r The location browser on the Situation tab uses the standard close button (the skin one in skin mode)",
        "|cff66bb6aChange:|r Every window's close button (normal mode) uses the addon's own close button instead of the game's",
        "|cff66bb6aChange:|r The waypoint support window (the ? beside Waypoints on the Situation tab) has full-width link buttons, the addon's own close and ? icons, greys the link for an addon you already have, and the ? goes away when you have both TomTom and WaypointUI",
        "|cff66bb6aChange:|r Clicking outside the manual waypoint row closes it when nothing was typed",
        "|cff66bb6aChange:|r Note Settings > General uses the full window width (no scroll area)",
        "|cff66bb6aChange:|r Note Settings > Situation has the same side margins as the other tabs",
        "|cff66bb6aChange:|r Every colour grid (sticky text and background, note title colour, New note, the Oracle's custom style) ends with a colour picker button in its last slot, replacing the separate \"Click to pick color\" box and the Custom color / Reset buttons",
        "|cff66bb6aChange:|r In skin mode, stickies you have not recoloured use the skin colour for their background, header and border, kept dark, and follow it when you change the skin",
        "|cff66bb6aChange:|r Sticky background opacity now defaults to 90% (was 96%); stickies still at 96% move to 90%",
        "|cff66bb6aChange:|r Skin brightness now defaults to 1.50",
        "|cff66bb6aChange:|r Simplified Chinese: the translation is complete again, every new text included",
        "|cff66bb6aFixed:|r The Show checkboxes under Settings > Modules > Oracle search > Results could not be switched off",
        "|cff66bb6aFixed:|r Picking an instance from the zone browser while the situation type said Zone saved it as a zone, so the note never showed there. The type now follows the tab you pick from (Situation tab and task editor)",
        "|cff66bb6aFixed:|r Setup wizard: the normal and skin mode pictures were squashed",
        "|cff66bb6aFixed:|r Settings > Modules > Sticky Notes showed the alarm page's description",
        "|cff66bb6aFixed:|r Rich notes: text after a closed {p} on the same line, or in a {p} never closed, made the whole note disappear",
        "|cff66bb6aFixed:|r Making a link from selected text deleted the text instead of linking it",
        "|cff66bb6aFixed:|r Tab and Shift+Tab move between the Insert Link fields",
        "|cff66bb6aFixed:|r A locked plain note now shows the lock cursor like a locked rich note",
        "|cff66bb6aFixed:|r Closing a Direct Send prompt with its X (normal mode) stopped later incoming notes from prompting until a reload",
        "|cff66bb6aFixed:|r Col, Lnk, Ico and Img did nothing in Focus mode (their windows opened behind it, or hidden with \"hide UI\")",
        "|cff66bb6aFixed:|r Closing Focus mode and then the main window quickly with ESC left the live preview open on its own",
        "|cff66bb6aFixed:|r Migrate Now (bringing notes over from another notes add-on) was blocked from reloading the UI; it now finishes with a \"Reload Now\" popup",
        "|cff66bb6aFixed:|r The Settings window opened behind the live preview",
        "|cff66bb6aFixed:|r A situation's waypoint kept the note's old title after the note was renamed; it now follows the title, also on the map right away",
        "|cff66bb6aFixed:|r Danger Zone > Factory Reset no longer gives a Lua error and a blocked reload: it wipes everything, then asks you to reload",
        "|cff66bb6aFixed:|r The character tabs on top of the main window show their tooltip below the tabs when the window is near the top of the screen",
        "|cff66bb6aFixed:|r \"Use WoW's default font\" now shows in the New note window's font preview",
        "|cff66bb6aFixed:|r The formatting toolbar's History button closes the History window again on a second click",
        "|cff66bb6aFixed:|r Copy / Move opens with its top-left corner at the pointer, and also opens with the Character sidebar off",
        "|cff66bb6aFixed:|r Sticky Note Settings on a minimized sticky restores it and opens its settings",
        "|cff66bb6aFixed:|r The Alarm overview showed the BigNoteBox logo for a note using the default icon",
        "|cff66bb6aFixed:|r The Reference Box showed a scrollbar with nothing to scroll",
        "|cff66bb6aFixed:|r Danger Zone's confirm countdown was half hidden under the scrollbar",
        "|cff66bb6aFixed:|r Settings > Backup > Data Summary updates at once after an import or delete",
        "|cff66bb6aFixed:|r A damaged JSON backup is refused with the line where it breaks, instead of importing only part of it",
        "|cff66bb6aFixed:|r Deleting the last snapshot of a note in Note History goes back to the list",
        "|cff66bb6aFixed:|r Note History and the Alarms window show a note's icon frame",
        "|cff66bb6aFixed:|r The Situation tab recognizes WaypointUI",
        "|cff66bb6aFixed:|r The tabs in Note Settings and Sticky settings no longer overflow the window border in skin mode",
        { retail = true, "|cff66bb6aChange:|r Main window resize grip sits closer into the corner (normal look)" },
        { forever = true, "|cff66bb6aChange:|r The character tabs on top of the main window (normal look) are wider, share the whole width, and tuck under the window's top border" },
        { forever = true, "|cff66bb6aChange:|r The insert image / link / icon dialogs, Copy/Move, Send to Chat, Send to Chat confirm, Direct Send prompt, Trash, BigChatBox and Import from other addons windows get the Forever window glow" },
        { forever = true, "|cff66bb6aChange:|r Main window resize grip sits closer into the corner, in normal and skin mode" },
        { forever = true, "|cff66bb6aFixed:|r The top character tabs no longer split their art after the window's position is reset" },
    } },
    { version = "1.18.0", time = 1791130344, entries = {
        "|cff66bb6aNew:|r A new icon picker in Note Settings: icons sorted into categories (Notes, Books, Classes, Races, Zones and more), with search. Tick \"All game icons\" to browse and search every icon in the game",
        "|cff66bb6aNew:|r A note can have several situations: the Situation tab lists them, with an Add row and an X on each, and the note shows when any one of them matches. A note with both places and players says \"When it starts / When it ends\". A new \"NPC / Mob\" situation works like Player, for notes about an NPC or a mob. A new \"Guild\" situation shows a note when you target, or group with, a player in that guild",
        "|cff66bb6aNew:|r New situations: \"Instance type\" (any dungeon, raid, delve (Retail) or battleground), \"Window open\" (vendor, bank, mailbox, auction house or trainer: shows a note when you open it, or when you close it) and \"Rested\" (in an inn or a city)",
        "|cff66bb6aNew:|r The character sidebar can sit on top of the main window as long tabs: each tab shows the character's icon, name and note count, with the same tooltip and right-click menu. With many characters the tabs get smaller, and the rest are in a \"More...\" menu at the end; picking a character there moves it to the front. Choose Top, Right or Left in Settings > Modules > Character sidebar",
        "|cff66bb6aChange:|r The main window's resize grip is bigger, with its own hover and pressed look",
        "|cff66bb6aChange:|r The divider lines in the note editor now all match: one thin grey line, the same as the Pinned divider in the note list",
        "|cff66bb6aChange:|r Note icons now come from the game itself, so the download is about 20 MB smaller. Your notes keep their icons",
        "|cff66bb6aChange:|r The New note window and the Insert icon window use the new icon picker. In Insert icon, type a full game icon name or file id into the search and press Enter to use any icon in the game",
        "|cff66bb6aFixed:|r The rich note live preview is no longer covered by the sidebar icons",
        "|cff66bb6aFixed:|r Typing a sub-zone in the Situation tab now suggests sub-zones (every area the game knows, in your language) instead of zone names",
        { retail = true, "|cff66bb6aNew:|r A metal header strip behind the sort menus and toolbar icons at the top of the main window (normal mode); the header is a little taller to fit it" },
        { forever = true, "|cff66bb6aNew:|r A quest log header strip behind the sort menus and toolbar icons at the top of the main window (normal mode)" },
        { forever = true, "|cff66bb6aChange:|r The icon lists show only the races in the game (the original eight), and a few newer icons the game does not have are gone; a note that used one shows the default icon" },
    } },
    { version = "1.17.0", time = 1791067798, entries = {
        "|cff66bb6aNew:|r The note list's right-click menu is rebuilt: a shorter menu with icons and sub-menus that open on hover (Open, Create, Actions, History), with the note's icon and title colour at the top. The Tag Manager's note rows use it too",
        "|cff66bb6aNew:|r A situation note can show when you arrive, when you leave, or both (Situation tab > Trigger), and as often as you choose: every time, once per session, once per day, once per daily or weekly reset, or only once. Counted for each character",
        "|cff66bb6aNew:|r Right-click in Select mode for a menu that works on every selected note: open as sticky notes, pin, favorite or lock all, duplicate, move, convert, export as JSON, Markdown or HTML, create restore points, clear history, clear alarms, remove tasks or situations, move to trash or delete",
        "|cff66bb6aNew:|r Create or edit a note's situation straight from its right-click menu (Create > Create situation)",
        "|cff66bb6aNew:|r History in the right-click menu: create or replace the restore point, clear the auto snapshots, and Restore previous lists the restore point and the latest snapshots to compare and restore",
        "|cff66bb6aNew:|r Settings > Modules > Right-click menu: choose what a click on Open note, Create, Actions and History does, and how fast the sub-menus open, with a Try it button",
        "|cff66bb6aNew:|r Right-click an Oracle search result for the same note menu",
        "|cff66bb6aNew:|r Remove all tasks from a note with its right-click menu (Create > Remove all tasks)",
        "|cff66bb6aChange:|r Every right-click menu (Tag Manager, alarms, history, sidebar, stickies, Reference Box, tasks, Insert Info) now uses the new menu, and entries that cannot be undone are shown in red",
        "|cff66bb6aChange:|r Shift+click a note to start Select mode, and click anywhere outside the note list to leave it",
        "|cff66bb6aChange:|r Selected notes in Select mode have their own highlight",
        "|cff66bb6aChange:|r Rich notes switch between Markup and Note with labelled tabs under the editor, each with its icon beside the name",
        "|cff66bb6aFixed:|r The Settings tabs no longer run over the edges of the window",
        "|cff66bb6aFixed:|r The note list menu now says \"Close note settings\" while Note Settings is open for that note",
        "|cff66bb6aFixed:|r Override and Compare in the \"restore point already exists\" popup did nothing",
        "|cff66bb6aFixed:|r Opening a note from outside the note list (Oracle search, menus) now scrolls the list to it, opening the main window and clearing a list search that hides it",
        "|cff66bb6aFixed:|r \"When you leave the area: Minimize\" chosen in a sticky's settings did nothing. Notes already set that way are repaired",
        "|cff66bb6aFixed:|r Factory Reset and Clear migration flags in the Danger Zone were blocked from reloading the UI and left an error instead",
        "|cff66bb6aFixed:|r The Reference Box opened from Oracle search (Alt+Enter) did not close on ESC after the main window had opened it once",
        "|cff66bb6aFixed:|r The Tag Manager showed above the Danger Zone's red overlay",
        "|cff66bb6aFixed:|r Clicking a situation popup now opens its note, also when several notes popped up at once, when the main window had not been opened yet, or when the note list was filtered to another character",
    } },
    { version = "1.16.0", time = 1791027475, entries = {
        "|cff66bb6aNew:|r Right-clicking the portrait of a player or NPC you have a note on now also offers \"Open BNB Sticky Note\"",
        "|cff66bb6aNew:|r Reference Box: \"Show model\" shows gear, mounts and battle pets in the model viewer on any note, turning slowly; grab it to turn, move or zoom, and it starts turning again 3 seconds after you let go. Gear is framed on its slot: a helm on the head, shoulders on the shoulders; weapons, shields and off-hands are shown on their own. Drag up and down to tilt, Shift+wheel to move it nearer, and hover the bottom of the viewer for turn, reset and animation buttons",
        "|cff66bb6aNew:|r Reference Box: clicking an entry now works like a link in chat: click to view it (model viewer, or its item window), Shift+click to put it in chat, Ctrl+click for the dressing room",
        "|cff66bb6aChange:|r Send to Chat sends party, raid, guild, officer and whisper lines a moment apart, so the server no longer drops lines of long notes, and shows a live count. Closing the window stops it",
        "|cff66bb6aChange:|r Send to Chat to Say or Yell sends one message per click on Send, since the game only allows those from a click",
        "|cff66bb6aChange:|r Direct Send paces itself to the server's limit, shows its progress, and tells you in chat when the note went out or why it could not be sent (player offline, blocked in an instance)",
        "|cff66bb6aChange:|r Typing in long notes is lighter: the word count, live preview and autosave wait for a pause in your typing instead of running on every key",
        "|cff66bb6aChange:|r The note list redraws only the note you are typing in, and only target notes when you change target, instead of the whole list",
        "|cff66bb6aChange:|r Note history now keeps the text, rich mode, tags and tasks of each version instead of a full copy of the note, so saved history takes far less space. Restoring a version leaves the note's icon, colours and font as they are now",
        "|cff66bb6aChange:|r Ticking a task or snoozing and dismissing an alarm no longer counts as editing the note, so it keeps its place in the \"Edited\" sort",
        "|cff66bb6aChange:|r Redrawn icon buttons (title bars, sticky headers, tasks, Reference Box, calendar), with a bronze edge on WoW Forever. In skin mode they now take the skin's colours, like every other skin button, instead of the stone look",
        "|cff66bb6aChange:|r Skin mode: the main window's title bar is now as tall as every other window's",
        "|cff66bb6aChange:|r Reference Box: item tooltips now open beside the window on the main window's side, with the \"Equipped\" comparison next to them, so they no longer cover the list",
        "|cff66bb6aFixed:|r Direct Send with auto-reject on printed one chat line for every piece of an incoming note; now one per note",
        "|cff66bb6aFixed:|r Situation waypoints were set again on every target change, taking the map tracking away from your quest",
        "|cff66bb6aFixed:|r Player situations now match members of a 5-player party, not only a raid, and are checked when someone joins",
        "|cff66bb6aFixed:|r Inspect notes for a party member you had not targeted were built from your target instead",
        "|cff66bb6aFixed:|r The book button stayed greyed out for the rest of the session if the book was closed while it was reading the pages",
        "|cff66bb6aFixed:|r Opening and closing sticky notes, ticking tasks and opening Settings used a little more memory every time, for the whole session",
        "|cff66bb6aFixed:|r A zone change checked your note situations two or three times over",
        "|cff66bb6aFixed:|r Hovering a sticky with high opacity snapped to full instead of fading; every hover fade now takes the same short time",
        "|cff66bb6aFixed:|r Hiding a character from the sidebar now shows in Settings > Modules > Character sidebar's Hidden characters list at once",
        "|cff66bb6aFixed:|r A sticky showing its tasks went blank when the last task was cleared or deleted; it now goes back to the note",
        "|cff66bb6aFixed:|r The maximum number of open sticky notes now starts at 20, the same value its Reset button gives",
        "|cff66bb6aFixed:|r Character sidebar on the left: small icons sat off-centre, and in normal mode the bar stood away from the main window",
        "|cff66bb6aFixed:|r Skin mode: the Reference Box's Model and Tasks tabs could draw over the window's edge",
        "|cff66bb6aFixed:|r The main window could jump toward the top of the screen as soon as you started dragging it",
        "|cff66bb6aFixed:|r The main window sometimes opened in the middle of the screen at its default size instead of where you left it",
        "|cff66bb6aFixed:|r Focus mode: the dark AFK screen now goes away when you move the mouse, as it was meant to",
        "|cff66bb6aFixed:|r A situation alert that fired again while the previous one was fading out vanished straight away",
    } },
    { version = "1.15.2", time = 1790970187, entries = {
        "|cff66bb6aFixed:|r Enter did not start a new line while editing a sticky note (since v1.15.0), and Ctrl+Enter could remove a line break",
    } },
    { version = "1.15.1", time = 1790947350, entries = {
        "|cff66bb6aChange:|r Sticky backgrounds now show in their own colours when you first pick one, instead of tinted by the note colour (on a dark note they all looked black). The background picker always shows them as they are. Turn \"Colorize texture\" up to tint a background again",
    } },
    { version = "1.15.0", time = 1790941562, entries = {
        "|cff66bb6aNew:|r Ctrl+J brings all sticky notes to the front (Key Bindings > BigNoteBox > Bring Sticky Notes to Front)",
        "|cff66bb6aNew:|r Esc or Ctrl+Enter finishes editing a sticky note (Enter still starts a new line)",
        "|cff66bb6aNew:|r Settings > Notes > \"Open Note Settings for new notes\": untick it to create new notes without Note Settings popping up",
        "|cff66bb6aNew:|r Icon frames. Give a note's icon a frame made from game art (52 to pick from), chosen in a new picker window with All, Square, Circle and Edge borders tabs that previews your own icon. The frame shows everywhere the note's icon does: the note list, sticky notes, the Reference Box, search results and Trash",
        "|cff66bb6aNew:|r Default keys. F6 makes a note from your target, F7 a quick note, F8 a new note. They are only set where the action had no key and the key was free, so your own bindings stay as they are",
        "|cff66bb6aNew:|r The quick note key now opens the new note as a sticky note in the middle of the screen, ready to type in. Close it without typing and it is gone. Prefer the main window? Settings > Modules > Quick Note",
        "|cff66bb6aNew:|r Danger Zone > Reset Key Bindings puts every BigNoteBox key back to its default, without touching keys the game or other addons use",
        "|cff66bb6aNew:|r Choose how often an alarm's sound repeats until you answer it: once, or every 10 seconds, 30 seconds, minute or 5 minutes (alarm window, under Sound). Every 10 seconds is the default, as before",
        "|cff66bb6aNew:|r Pick what to share with checkboxes: tags, tasks, Reference Box, look, situation and unit data, in any mix. Title and text always go along. Your choice is remembered, and Send to player uses it too",
        "|cff66bb6aNew:|r Select several notes and press Export to get them as one JSON export, ready for Settings > Backup > Import",
        "|cff66bb6aNew:|r After a backup import, a line in chat says how many notes came in, how many were skipped and why, and how many had tasks, an alarm or Reference Box items",
        "|cff66bb6aChange:|r Sticky notes now act like windows: whichever you clicked last is in front, so the main window can cover them. Ctrl+J brings them all forward, and Settings > Modules > Sticky notes > \"Keep sticky notes above BigNoteBox windows\" keeps them on top as before",
        "|cff66bb6aChange:|r A single alarm missed while you were offline now shows just its popup; the Alarms overview opens only when several were missed",
        "|cff66bb6aChange:|r A quick note made with the Quick Note button or key in the main window is removed again if you leave it empty, the same as a quick sticky note",
        "|cff66bb6aChange:|r Reference Box items on a locked note keep their colour; the lock icon shows they cannot be removed",
        "|cff66bb6aChange:|r The alarm time can be typed: hour and minute are input fields (Tab or : moves between them) that still open a list from their arrow. Any minute can be set, not only steps of 5, a new alarm starts at the current time, and with a 12-hour clock (Appearance > Timestamp format) the hour runs 1-12 with an AM/PM field",
        "|cff66bb6aChange:|r Alarms glow steadily by default. Pick Pulse in the alarm window for 10 seconds on, 10 seconds off (until now Pulse looked steady because of a bug that restarted the glow)",
        "|cff66bb6aChange:|r An alarm that goes off in combat posts one line in chat and glows on its note (also on an open or minimized sticky note); its sound and window follow when combat ends. The alarm, Note Settings and sticky settings windows are now as large as the Reference Box",
        "|cff66bb6aChange:|r Every slider now looks the same: name and default on top, the value beside it, and a Reset button next to the slider. Settings, sticky settings, Note Settings, alarms, the New Note window and the setup wizard all use it",
        "|cff66bb6aChange:|r A JSON backup now holds everything about a note: tasks, text size, icon frame, where it was made, player and NPC details, and the full alarm. Backups made with older versions still import",
        "|cff66bb6aChange:|r Share strings now start with BNB2: and carry tasks and sub-tasks. Older BNB1: strings still import. Players on an older version of BigNoteBox cannot read the new strings, or notes you send them directly, until they update",
        "|cff66bb6aChange:|r A shared note lands under the character you have selected in the sidebar, not under the sender's character, and never brings the sender's alarm, pin or lock",
        "|cff66bb6aFixed:|r The reset filter button now lights up as soon as you type in the search box",
        "|cff66bb6aFixed:|r A tab character in an imported or shared note showed as a box; it now becomes spaces",
        "|cff66bb6aFixed:|r Importing a backup with another character's notes and choosing \"Keep original\" imported nothing",
        "|cff66bb6aFixed:|r The zone and instance browser in Sticky settings opened behind the window and in the wrong place",
        "|cff66bb6aFixed:|r The zone browser button in the task editor did nothing (it threw an error)",
        "|cff66bb6aFixed:|r \"Reset to default\" for a note's font size in Note Settings kept the size instead of going back to the global one, and switching notes with Note Settings open could save the sliders' values into the new note",
        "|cff66bb6aFixed:|r The mouse wheel no longer changes sliders (in the setup wizard it still did); it scrolls the page",
        "|cff66bb6aFixed:|r A ringing alarm now glows on the note's icon in the note list too, as it already did in the alarm overview",
        "|cff66bb6aFixed:|r Moving a note to two or more characters at once only moved it to the first; the others now get a copy",
        "|cff66bb6aFixed:|r Dragging an item into a note did nothing if you had not seen that item yet this session",
        "|cff66bb6aFixed:|r Clearing the search box now also closes the tag suggestions under it",
        "|cff66bb6aFixed:|r Picking the OLED skin preset now greys out the brightness and opacity sliders straight away",
        "|cff66bb6aFixed:|r Shift-clicking a Reference Box item to send it to chat could also try to add it again and print \"full\" or \"locked\"",
        "|cff66bb6aFixed:|r The \"Delete completed tasks\" button showed the single-task tooltip \"Delete task\"",
        "|cff66bb6aFixed:|r Starting the setup wizard again now closes the share, alarm, history and preview windows",
        "|cff66bb6aFixed:|r The minimap button's tooltip now shows how many notes match where you are; the line never appeared",
        "|cff66bb6aFixed:|r Restoring a JSON backup lost every on/off setting of a note: pinned, favourite, locked, rich note, and an alarm's weekdays. Rich notes came back as plain text with the markup showing",
        "|cff66bb6aFixed:|r A single note exported as JSON (right-click > Export note) could not be imported in Settings > Backup. It now can, and so can notes exported that way before this version",
        "|cff66bb6aFixed:|r Character notes brought over from another notes addon only showed under \"All\". They now sit under their character, including notes you already moved over",
        "|cff66bb6aFixed:|r The Reference Box could delete an item, spell or quest from a note when the game was slow to load it, or did not know it (a retired quest, an item from the other game client). It is now kept and shown as unavailable, and you decide whether to remove it",
        "|cff66bb6aFixed:|r Importing or moving many notes at once could, rarely, overwrite one note with another",
        "|cff66bb6aFixed:|r Restoring a note from History now updates its tags in the Tag Manager, and a saved version no longer changes when you tick a task afterwards",
        "|cff66bb6aFixed:|r Delete All Notes in the Danger Zone now also closes open sticky notes and clears the old tags",
        "|cff66bb6aFixed:|r With many notepad addons installed, the \"move your notes over\" window ran off the bottom of the screen and its buttons could not be reached. The list now scrolls",
        "|cff66bb6aFixed:|r Alarm sounds other than Default never played when the alarm went off (only the Test button played them)",
        "|cff66bb6aFixed:|r Alarms set to an in-game (server) time never went off. They now ring at that time",
        "|cff66bb6aFixed:|r A ringing alarm restarted itself every 10 seconds, so its glow animation started over each time and a sticky note alarm in combat printed a chat line every 10 seconds. It now rings once, and a sticky note alarm opens when combat ends",
        "|cff66bb6aFixed:|r Alarms did not go off at all in Focus mode with \"hide UI\" on. They now ring and show their popup on top of Focus mode, and the AFK screen cover shows again",
        "|cff66bb6aFixed:|r The \"WoW weekly reset\" alarm and the daily and weekly task resets used a fixed Tuesday 07:00. They now follow your region's real reset times",
        "|cff66bb6aFixed:|r A daily, weekly or \"every N days\" task unticked itself within a minute the first time you ticked it",
        "|cff66bb6aFixed:|r Moving an alarm that had already gone off to a new time did nothing until you pressed Reset in the alarm overview. Saving a new time now sets it again",
        "|cff66bb6aFixed:|r When two alarms went off together, the first one lost its popup and could not be dismissed. They now take turns",
        "|cff66bb6aFixed:|r With \"Confirm before closing\" on and the window set to hide in combat, entering combat brought the window straight back with a close confirmation. It now stays hidden until combat ends",
        "|cff66bb6aFixed:|r With a BigNoteBox window open in combat, every key press caused an \"action blocked\" error and ability keys could stop working. In combat the windows now leave the keyboard to the game: your keys work as normal, and ESC does what the game does (closes the windows it knows, clears your target or opens the game menu). The Send to Chat window and the BigChatBox promo no longer hold on to keys you press while they are open",
        "|cff66bb6aFixed:|r A JSON backup with an in-game time alarm caused an error after restoring it, and lost the alarm's after-combat setting. Backups made before this version restore correctly",
        "|cff66bb6aFixed:|r Restoring a JSON backup lost every note's tasks, and a note whose text had a lone { or } could take the notes after it down with it",
        "|cff66bb6aFixed:|r Shared notes lost their tasks and gear lists, and a waypoint name or tag with a comma in it came out cut in two",
        "|cff66bb6aFixed:|r The Quick Note \"confirm\" window showed an empty title, or the title of the quick note before it",
        "|cff66bb6aFixed:|r After a settings reset, the \"move your notes over\" window offered the same addon again, and accepting it copied all those notes a second time",
        "|cff66bb6aFixed:|r Restoring a backup from the welcome page did nothing when the backup held notes for another character",
        "|cff66bb6aFixed:|r Notes restored from a backup showed the time of the restore as their last edit",
        { retail = true, "|cff66bb6aFixed:|r The instance browser in a note's Situation settings now shows the expansion name beside each dungeon and raid" },
        { forever = true, "|cff66bb6aFixed:|r BigNoteBox no longer recognised WoW Forever after the October 1 client update, so windows lost their Forever spacing, glows and art and looked cramped" },
    } },
    { version = "1.14.0", time = 1790601707, entries = {
        "|cff66bb6aNew:|r Oracle search: press Ctrl+Space anywhere to search all your notes, then open one in the main window. Hold Shift to open it as a sticky, Ctrl for Focus mode, or Alt for the Reference Box. Also /bnb search",
        "|cff66bb6aNew:|r Oracle search prefixes: start with a letter and a space to narrow the search, e.g. \"p\" player notes, \"n\" NPC notes, \"t\" notes with tasks, \"d week\" edited this week, \"s\" to open as a sticky. Also #tag, @name, -word, \"exact phrase\" and * for favourites. Type ? for the full list with examples",
        "|cff66bb6aNew:|r Oracle search ranks by what matters now: your target's note, notes for this zone and this character, favourites, recently opened or edited notes and alarms due soon come first, even with an empty box",
        "|cff66bb6aNew:|r Oracle search results show small icons for what a note is: NPC, elite, player (Alliance or Horde), quest, item, rich note, and notes with a situation or an alarm",
        "|cff66bb6aNew:|r Oracle search themes: Eye of Kilrogg, Alliance and Horde",
        "|cff66bb6aNew:|r Oracle search settings (Settings > Modules > Oracle search, or right-click the bar): theme, how many results, move the bar where you want it with a live preview, how notes open, keep the bar open to open several notes, and how much each ranking boost counts. The bar starts a little above the middle of the screen, in your faction's theme",
        "|cff66bb6aNew:|r Oracle search: a Custom border theme. Set it up like a sticky note: background colour and texture (the sticky note backgrounds, with the thumbnail picker), Colorize, brightness and opacity, border style, thickness, offset and brightness, the colour of the selected result, and a font (BigNoteBox fonts or LibSharedMedia) with its size. Start from the built-in Default style (a Blizzard window frame) or Plain, save your own styles, and share them with Export and Import. Other addons can register box themes like it",
        "|cff66bb6aNew:|r Oracle search results: a Results section in its settings sets the title and preview text size, the note icon size and the badge size, and can hide the icons or the badges. Whose note it is shows as the rightmost badge: a globe for global notes, otherwise the character's class icon in a circle, with the name on hover",
        "|cff66bb6aNew:|r The setup wizard's keybinding page now also lists Create note from target and Oracle search",
        "|cff66bb6aNew:|r Timestamp button in the note toolbar, right of the bullet button: insert the date, the time, or both at the cursor, in your timestamp format from Settings > Appearance",
        "|cff66bb6aNew:|r Choose what double-clicking a note in the list does (Settings > Notes): note settings, just open, sticky, ESC sticky, Focus mode, alarm, task, or switch lock, favorite or pin",
        "|cff66bb6aNew:|r Open as sticky note and Open as ESC sticky note close the sticky when it is already open that way. The right-click menu then says Close sticky note, so you can see that a note has a sticky open",
        "|cff66bb6aNew:|r Eye button in the main window title bar to hide and show all sticky notes. It shows a closed eye while they are hidden. Hiding them (also with the Ctrl+H keybind) now says so in chat, with the key to bring them back, and so does logging in with them still hidden. The minimap button tooltip shows it too",
        "|cff66bb6aNew:|r Double-click a rich note in View mode to open the editor",
        "|cff66bb6aNew:|r Mouse cursors that show what you can do: the move cursor over window title bars, a resize arrow on resize grips and splitters, a hand when you drag a note or turn the Reference Box model, and a lock over the text of a locked note. Silver on Retail, gold on WoW Forever",
        "|cff66bb6aNew:|r Tasks can be switched off (Settings > Modules > Tasks). Off hides the Tasks button, the task panel, the note list menu entry and filter, and the sticky task view. Your tasks are kept and come back when you switch it on",
        "|cff66bb6aNew:|r Use server time (Settings > Appearance): timestamps, the welcome clock, inserted dates and alarms show the server clock instead of your computer's, and alarm times are entered in server time. Everything is still saved with the real time, so switching it off changes nothing",
        "|cff66bb6aNew:|r 50 new sticky note backgrounds (45 on Retail) taken from the game's own art: stone, wood, parchment, skies, scenery and profession scenes. Each one fills the note in the way that suits it (tiled, scaled to cover, or anchored) and takes your note colour and Colorize setting. Pick one in sticky settings from a grid of thumbnails, each showing your note with that background and sorted into tabs by look, or step through them with the < and > arrows",
        "|cff66bb6aNew:|r Texture brightness slider for sticky note backgrounds, under Colorize texture: make the background art brighter or darker without changing the note colour",
        "|cff66bb6aNew:|r Sticky notes get a \"Window\" background, the main window's own (rock on Retail, wood on Forever)",
        "|cff66bb6aChange:|r Settings: less empty space between the tabs and the settings below them",
        "|cff66bb6aChange:|r Sticky note settings: every slider has its name and value on one line above a full-width slider, like Note settings, instead of the name wrapping beside it",
        "|cff66bb6aChange:|r The Reference Box keeps a fixed height, the same as Note settings, instead of stretching with the main window",
        "|cff66bb6aChange:|r Turning the Reference Box off hides its button under the note instead of greying it, and the other buttons close the gap",
        "|cff66bb6aChange:|r Focus mode is greyed out for a locked note. Unlock the note to use it",
        "|cff66bb6aChange:|r The Send to chat button sits a little further from the main window's resize corner",
        "|cff66bb6aChange:|r The right-click Insert Info menu offers Date, Time, and Date and time, in your timestamp format from Settings > Appearance, like the toolbar button",
        "|cff66bb6aChange:|r Sticky notes fade smoothly to full opacity while the pointer is anywhere on them, rich and task notes included, and fade back when it leaves",
        "|cff66bb6aChange:|r The selected note in the note list, and the drop line and dragged note in Custom sort, are BNB green",
        "|cff66bb6aChange:|r Tasks work without the Reference Box: with the Reference Box off, the Tasks button under the note opens the tasks in a window of their own",
        "|cff66bb6aChange:|r The Reference Box title says what it shows: Reference, Reference + Model, Reference + Tasks, Reference + Model + Tasks, or Tasks",
        "|cff66bb6aChange:|r Editing the text of a checked task unchecks it, so a changed task is not left marked done",
        "|cff66bb6aChange:|r EB Garamond is drawn larger for the same font size, so it no longer looks smaller than the other fonts",
        "|cff66bb6aChange:|r The \"Add tag...\" field under a note is easier to see",
        "|cff66bb6aChange:|r Task list: hover a task to get an X that deletes it right away and a + that adds a sub-task (both only while hovering). The > arrow only shows on tasks that have sub-tasks",
        "|cff66bb6aChange:|r The original sticky backgrounds moved to their own small addon, BigNoteBox Backgrounds. It comes in the same download and only loads when a note uses one of them. Notes that use them look the same. With that addon removed or disabled, they show their plain colour until it is back",
        "|cff66bb6aFixed:|r Settings > Modules > Focus mode: \"Tint overlay with skin color\" is greyed out in normal mode, where it does nothing",
        "|cff66bb6aFixed:|r In-game alarms fire at the server time you set, not your computer's local time at that hour",
        "|cff66bb6aFixed:|r Skin mode: the Reference Box Model and Tasks tabs no longer draw on top of the window",
        "|cff66bb6aFixed:|r The X in Focus mode closes only Focus mode and brings back the main window, same as Esc",
        "|cff66bb6aFixed:|r Custom sort: a dragged note now lands exactly where the drop line shows. This also works with the sidebar, favourite or task filter on, in the collapsed list, and with pinned notes",
        "|cff66bb6aFixed:|r Opening a note as an ESC sticky a second time no longer turns it into a normal sticky. Before, it alternated on every open and stayed that way after a reload",
        "|cff66bb6aFixed:|r Esc with an ESC sticky open over the game menu closes the game menu first, not the BigNoteBox windows behind it",
        "|cff66bb6aFixed:|r The window scale lock tooltip switches between Locked and Unlocked as soon as you click it",
        "|cff66bb6aFixed:|r More interface text can now be translated: the markup bar tooltips, Tag Manager buttons, waypoint chat messages, sticky note settings headers and a few settings tooltips",
        "|cff66bb6aFixed:|r Resizing a window from its bottom-right grip no longer makes it jump, grow or shrink when you click the grip, or fill the whole screen. The window also can no longer be sized past the screen edge",
        { forever = true, "|cff66bb6aNew:|r A soft glow behind the note area in the main window, like the one behind the note list" },
        { forever = true, "|cff66bb6aNew:|r New action bar icons under the note, drawn for WoW Forever, and a little bigger so the detail shows" },
        { forever = true, "|cff66bb6aNew:|r Rich notes switch between Markup and Note with two tabs under the window, in the Forever style" },
        { forever = true, "|cff66bb6aNew:|r The WoW Forever notice at login has a new ornate frame" },
        { forever = true, "|cff66bb6aFixed:|r Your character no longer shows up twice (first name, and first name plus surname) in the sidebar and in Copy / Move Note" },
    } },
    { version = "1.13.0", time = 1790435859, entries = {
        "|cff66bb6aNew:|r Right-click menus in Note History: Compare, Restore and Delete for each saved version. Restoring no longer has to go through the Compare window",
        "|cff66bb6aNew:|r Right-click menus in the History window: open a note's history, open the note, or clear that note's history",
        "|cff66bb6aNew:|r Right-click menus in the Tag Manager: rename, delete or show the notes of a tag. A note under a tag gets the usual note menu, plus Remove this tag",
        "|cff66bb6aNew:|r Right-click a sticky note (title bar, body, icon or minimized tile) for Open in editor, Settings, Alarm, Show tasks, Minimize or Restore, and Close",
        "|cff66bb6aChange:|r Settings have been restructured. Every feature now has its own row on the new Modules tab, with its on/off switch where it has one and a Settings button that opens a page with all of that feature's options. The Back button returns you to the list",
        "|cff66bb6aChange:|r Skin mode: the editor toolbar buttons now use skin buttons, including the rich note markup bar (H1, P, Col, Img and the rest, plus Live Preview) in both the editor and Focus mode",
        "|cff66bb6aChange:|r Skin mode: the Danger Zone buttons now follow your skin colour instead of always being red",
        "|cff66bb6aFixed:|r The Ascending/Descending sort direction dropdown could still be clicked in tag tree view, even though it does nothing there. It now greys out along with the sort dropdown",
        "|cff66bb6aFixed:|r Skin mode: every window now follows the Window opacity setting. Several (sticky note settings, alarm and task windows, Focus mode, the feature list, and the main window after leaving Focus mode) always kept a little transparency, even at 1.00",
        "|cff66bb6aFixed:|r Right-click menus now open at the mouse pointer. Several opened beside the row instead, some (tasks, attachments) past the edge of the window",
        "|cff66bb6aFixed:|r A right-click menu no longer stays open after its window is closed",
        "|cff66bb6aFixed:|r Skin mode: the Reference box's Model/Tasks switch is now the same icon side tabs normal mode uses, instead of the old text buttons underneath the window",
    } },
    { version = "1.12.0", time = 1790348684, entries = {
        { retail = true, "|cff66bb6aNew:|r Report a bug button beside the Settings window, with links to GitHub, CurseForge, Wago and WoWInterface" },
        { forever = true, "|cff66bb6aNew:|r Report a bug button next to the main window during the beta, with links to GitHub, CurseForge, Wago and WoWInterface" },
        "|cff66bb6aChange:|r New BigNoteBox logo and addon list icon",
        "|cff66bb6aChange:|r The version compare window now shows tasks alongside the note text, not just the body",
        "|cff66bb6aChange:|r The right-click menu now offers 'Create BNB Note' next to 'Open BNB Note' when a note already exists, so you can make a second note from it",
        "|cff66bb6aChange:|r A second note for the same NPC is now named 'Name (Duplicate)', the same as player notes, instead of 'Name (1)'",
        { forever = true, "|cff66bb6aChange:|r The Edit Task window now has the same background glow as the other windows" },
        "|cff66bb6aFixed:|r The Blizzard icon name field in Note Settings showed a box inside a box, and clicking near its edge did not select it or clear the hint text",
        "|cff66bb6aFixed:|r Icon suggestions in Note Settings stopped closing when you clicked away after switching notes",
        "|cff66bb6aFixed:|r The wowhead.com/icons link in Note Settings now opens a box to copy the address",
        "|cff66bb6aFixed:|r The Direct send name field in Share Note showed a box inside a box",
        "|cff66bb6aFixed:|r Notes created from a player or NPC (inspect, target, portrait menu) now write their text, tags and gear slot names in your game language instead of English",
        "|cff66bb6aFixed:|r Notes for NPCs showed a question-mark icon instead of the creature type icon on non-English clients",
        "|cff66bb6aFixed:|r Player notes for a character without a specialization said the class twice ('Rogue Rogue') and got the class tag twice",
        "|cff66bb6aFixed:|r Restoring an older note version did not bring back its tasks or rich text formatting",
        "|cff66bb6aFixed:|r Task changes did not show up in an open note after restoring an older version, until you reopened it",
        "|cff66bb6aFixed:|r The 'Compare' button when creating a manual restore point did nothing",
        "|cff66bb6aFixed:|r Right-clicking a player of the other faction had no 'Create BNB Note' option",
        "|cff66bb6aFixed:|r The right-click menu now shows 'Open BNB Note' for a player you already have an inspect note for",
        "|cff66bb6aFixed:|r In a new rich player note (from Inspect), the text cursor could sit in the wrong place below the Notes heading",
        "|cff66bb6aFixed:|r Inspecting a player you already have a note for now shows the 'note exists' window again, and automatic inspect notes no longer make a new duplicate note every time you inspect the same player",
        "|cff66bb6aFixed:|r In skin mode, the Note Task Defaults window was titled 'Edit Task'",
        "|cff66bb6aFixed:|r Adding a task could leave the Tasks pane blank, showing 'Tasks (0/1)' with no tasks and no way to add one until you reloaded, and empty tasks you never typed into piled up",
        "|cff66bb6aFixed:|r In skin mode, the divider lines in Sticky Note Settings now take the skin colour, like every other window",
    } },
    { version = "1.11.1", time = 1790273369, entries = {
        "|cff66bb6aChange:|r Deleting 2 or more notes always asks first, naming the notes",
        "|cff66bb6aChange:|r Trash window: Delete selected asks first",
        "|cff66bb6aFixed:|r Select All selected notes hidden by a search or tag filter",
        "|cff66bb6aFixed:|r A just-deselected note still looked selected in multi-select",
        "|cff66bb6aFixed:|r The Select button sometimes needed two clicks",
        "|cff66bb6aFixed:|r Deleting many notes at once froze the game for a moment",
        "|cff66bb6aFixed:|r 'Delete permanently' moved the note to Trash",
        "|cff66bb6aFixed:|r With Trash off, deleted notes were kept in a hidden Trash",
        "|cff66bb6aFixed:|r Multi-select stayed on after closing the window or Focus mode",
        "|cff66bb6aFixed:|r Duplicate and Copy/Move keep rich mode, tasks and all settings",
        "|cff66bb6aFixed:|r A copied note shared its tags with the original",
        "|cff66bb6aFixed:|r Empty gap in the toolbar with Trash turned off",
        { retail = true, "|cff66bb6aFixed:|r What's New, Feature List and Setup glow sat too far left" },
    } },
    { version = "1.11.0", time = 1790252947, entries = {
        "|cff66bb6aNew:|r Notes save automatically while you type (can be turned off)",
        "|cff66bb6aNew:|r Double-click a sticky note to edit it in place",
        "|cff66bb6aNew:|r NPC notes show the NPC's face in the list and on stickies",
        "|cff66bb6aNew:|r Inspected player notes show their face while targeted",
        "|cff66bb6aNew:|r Reference box: Model and Tasks are now icon tabs on its side",
        "|cff66bb6aNew:|r The model viewer shows a Horde or Alliance crest",
        "|cff66bb6aNew:|r Stickies show the lock, situation and character markers",
        "|cff66bb6aNew:|r Quick Note says 'Note created' in chat",
        "|cff66bb6aChange:|r Right-click an open sticky's icon to close it",
        "|cff66bb6aChange:|r Humanoid NPC notes without a portrait use a neutral icon",
        "|cff66bb6aChange:|r The Focus window always opens at screen centre",
        "|cff66bb6aChange:|r Quick Note buttons look pressed when clicked",
        "|cff66bb6aFixed:|r Boxes shown instead of dashes, bullets and arrows",
        "|cff66bb6aFixed:|r Insert bullet point button took focus from the note",
        "|cff66bb6aFixed:|r Export buttons in the restore comparison window",
        "|cff66bb6aFixed:|r Inspect window note button stayed greyed out for some players",
        "|cff66bb6aFixed:|r Show model viewer button spacing",
        "|cff66bb6aFixed:|r Adding a task to an NPC or player note shows the Tasks tab",
        "|cff66bb6aFixed:|r 'Open in BigNoteBox to edit' puts the cursor in the note",
        "|cff66bb6aFixed:|r Alarm glow colour updates the preview straight away",
        "|cff66bb6aFixed:|r Minimizing a sticky keeps its icon in place",
        "|cff66bb6aFixed:|r 'Dim screen behind ESC sticky notes' could not be turned back on",
        "|cff66bb6aFixed:|r Tag Manager: clicking an open tag closes it again",
        "|cff66bb6aFixed:|r Unsaved changes are saved on logout and /reload",
        "|cff66bb6aFixed:|r Lua error when dragging the Reference box Move/Copy window",
        "|cff66bb6aFixed:|r Reference box Clear and Delete task buttons: colour and spacing",
        { forever = true, "|cff66bb6aChange:|r A soft glow lifts panels off the wood background" },
        { forever = true, "|cff66bb6aChange:|r Setup wizard shows a Forever preview for Normal mode" },
        { forever = true, "|cff66bb6aChange:|r Darker stone background for Reference box tasks" },
        { forever = true, "|cff66bb6aFixed:|r Player notes use the full name, surname included" },
        { forever = true, "|cff66bb6aFixed:|r Quick Note button position on the inspect window" },
    } },
    { version = "1.10.0", time = 1790193913, entries = {
        "|cff66bb6aNew:|r Traditional Chinese clients get their own font picker set",
        "|cff66bb6aChange:|r Buttons now use Blizzard's current, sharper button style",
        "|cff66bb6aFixed:|r Note settings: Use Default and Random icon buttons sat below the edge",
        { forever = true, "|cff66bb6aChange:|r Sidebar slot borders match Forever's own UI art" },
        { forever = true, "|cff66bb6aChange:|r Windows use a wood-grain background" },
        { forever = true, "|cff66bb6aFixed:|r Window borders no longer crowd the contents" },
    } },
    { version = "1.9.0", time = 1790166427, entries = {
        "|cff66bb6aNew:|r Language selector: English or Simplified Chinese, whatever your client",
        "|cff66bb6aNew:|r Chinese font set: WoW Hei and WoW Kai in the pickers when Chinese is active",
        "|cff66bb6aNew:|r Font packs: BigNoteBox Fonts CN adds six Chinese fonts",
        "|cff66bb6aFixed:|r The font picker is a clean 8-font grid again, WoW's font is a checkbox",
        "|cff66bb6aFixed:|r LibSharedMedia fonts are a dropdown in sticky and New Note font pickers",
        "|cff66bb6aFixed:|r Sticky note titles in Chinese or Korean showed as boxes",
        "|cff66bb6aFixed:|r Chinese clients: deleting a tag caused an error",
        "|cff66bb6aFixed:|r Chinese translation completed for the migration windows",
    } },
    { version = "1.8.0", time = 1790102220, entries = {
        "|cff66bb6aNew:|r Support for WoW Forever, as a beta",
        "|cff66bb6aNew:|r Simplified Chinese (zhCN) translation",
        "|cff66bb6aChange:|r The setup wizard's dimming is lighter, so the world shows through",
        "|cff66bb6aChange:|r The WaypointUI and TomTom buttons now open a copy box with the link",
        "|cff66bb6aFixed:|r Chinese and Korean clients showed boxes instead of text on buttons",
        "|cff66bb6aFixed:|r The font lists sometimes showed only Noto Serif until a /reload",
        "|cff66bb6aFixed:|r Outline names and some note settings headers are now translated",
        "|cff66bb6aFixed:|r Esc in the setup wizard now asks before closing",
        "|cff66bb6aFixed:|r The Waypoint Support window now closes with Esc",
        "|cff66bb6aFixed:|r A copy box could get stuck on screen after its window closed",
        "|cff66bb6aFixed:|r Two tooltips showed a stray code or a box instead of the right character",
        "|cff66bb6aFixed:|r WoW Forever: the glow around several windows was cut off",
    } },
    { version = "1.7.4", time = 1789978739, entries = {
        "|cff66bb6aNew:|r Added a WoW Default font option that uses the game client's own font",
        "|cff66bb6aNew:|r Chinese, Korean and Japanese clients now default to that font on first use",
        "|cff66bb6aChange:|r Finished localizing the interface, so all text can be translated",
        "|cff66bb6aChange:|r Updated LibTourist, adding the new Midnight zones and delves",
        "|cff66bb6aChange:|r Updated LibCustomGlow, fixing the alarm glow on newer clients",
        "|cff66bb6aFixed:|r Right-clicking a task checkbox in RefBox also toggled the task",
        "|cff66bb6aFixed:|r Changing a task's reset type kept the old reset timestamp",
    } },
    { version = "1.7.3", time = 1778592185, entries = {
        "|cff66bb6aNew:|r Blizzard icon fields (Note config and Rich Note Ico tag) now support autocomplete search across 32,000+ icons",
        "|cff66bb6aNew:|r Type any part of an icon name to get suggestions with live previews. You can scroll the list with arrow keys and mouse wheel",
        "|cff66bb6aNew:|r Enable the icon list feature in Main Config > Advanced > Icons (off by default). This feature uses ~2 MB of memory",
        "|cff66bb6aChange:|r Default max amount of sticky notes changed from 10 > 20",
    } },
    { version = "1.7.2", time = 1778497112, entries = {
        "|cff66bb6aNew:|r You can now migrate notes from MyNotepad and AmmeNotepad",
        "|cff66bb6aNew:|r Sticky Notes can now live in the ESC menu screen (Sitcky Note Config > Pin to ESC Screen )",
        "|cff66bb6aNew:|r Sticky Notes can be set to always open in the ESC menu screen (Main Config > Features > Sticky Notes > Default to ESC screen only)",
        "|cff66bb6aNew:|r There is an overlay by default on the ESC screen, this can be turned off (Main Config > Features > Sticky Notes > Dim screen behind ESC sticky notes)",
        "|cff66bb6afixed:|r Dropdown menues i Sticky Note settings rendered below the window",
    } },
    { version = "1.7.1", time = 1778488002, entries = {
        "|cff66bb6aNew:|r Sticky notes now have a focus mode. Open the sticky note settings and check Focus Mode",
        "|cff66bb6aChange:|r Removed eight background textures for sticky notes and added three new ones",
        "|cff66bb6aChange:|r Added a separate buttons graphic to when a sitcky note is in task mode, the button that switchs back to note mode is now a note",
        "|cff66bb6aFixed:|r The buttons in the task window now show as disabled when there are no tasks to clear/delete both in normal mode and skin mode",
        "|cff66bb6aFixed:|r Task mode in Sticky Notes should no longer flicker if the opacity is set to anything but 100% ",
        "|cff66bb6aFixed:|r Setting a situation or reset on a sub-task will now correctly show the icon in the task window in refbox",
    } },
    { version = "1.7.0", time = 1778362548, entries = {
        "|cff66bb6aNew:|r Task system! Add tasks and sub-tasks to any note",
        "|cff66bb6aNew:|r Tasks can have daily or weekly auto-reset (set in the task edit window)",
        "|cff66bb6aNew:|r Tasks can be bound to a situation (zone, instance, player) (set in the task edit window)",
        "|cff66bb6aNew:|r Sub-tasks can collapse and expand",
        "|cff66bb6aNew:|r Task panel in the Reference Box with header, footer, and splitter",
        "|cff66bb6aNew:|r Sticky notes can show task view instead of note body (toggle with the task button in the sticky header)",
        "|cff66bb6aNew:|r Task view in sticky notes with live checkbox toggling",
        "|cff66bb6aNew:|r Task filter button in the note list",
        "|cff66bb6aNew:|r Task icon shown in note list rows for notes with tasks",
        "|cff66bb6aNew:|r Tasks added as a share tier in the share system",
        "|cff66bb6aNew:|r Global reset and situation icons in sticky note task footer",
        "|cff66bb6aNew:|r Task list spacing setting -- Compact, Normal, Spacious (Config > Features > Tasks)",
        "|cff66bb6aNew:|r Stone background texture added to sticky note appearance (Sticky Settings > Appearance)",
        "|cff66bb6aChange:|r Background opacity in sticky notes can now be set to 0 (Sticky Settings > Appearance)",
        "|cff66bb6aChange:|r Sticky note task footer shows Tasks and Sub-tasks counts separately",
        "|cff66bb6aChange:|r Task toggle buttons match the Reference Box style",
    } },
    { version = "1.6.9", time = 1778164999, entries = {
        "|cff66bb6aAdded:|r You can now migrate notes from PurpleNotes, SimpleNote, QuickNote and OneWoW Notes",
